/* Vragenbank PA-toets, Wft Pensioen. Vorm: [vraag, [[antwoord, uitleg] x4], toetsterm CDFD]; het EERSTE antwoord is steeds het juiste.
   Gegenereerd met tools/vragen-js.py. */
(window.PA_VRAGEN = window.PA_VRAGEN || {})["pensioen"] = [
["Uit welke drie pijlers bestaat het Nederlandse pensioenstelsel?", [["AOW, werkgeverspensioen en individuele aanvullingen", "De eerste pijler is de AOW, de tweede het pensioen via de werkgever en de derde de individuele voorzieningen zoals lijfrente."], ["AOW, Anw en werkgeverspensioen", "De Anw is een nabestaandenvoorziening binnen de sociale zekerheid en geen aparte pensioenpijler."], ["Werkgeverspensioen, lijfrente en vermogen in de eigen woning", "De eigen woning kan financieel helpen na pensionering, maar is geen pensioenpijler."], ["AOW, bijstand en individuele aanvullingen", "Bijstand is een vangnet via de Participatiewet en hoort niet bij de pensioenpijlers."]], "1h.3"],
["Tot welke pijler behoort een lijfrenteverzekering die een zelfstandige zonder personeel zelf afsluit?", [["De derde pijler", "Individuele, op eigen initiatief getroffen voorzieningen zoals lijfrente en banksparen vormen de derde pijler."], ["De eerste pijler", "De eerste pijler is de AOW, een volksverzekering die niet door eigen keuze wordt opgebouwd."], ["De tweede pijler", "De tweede pijler is het pensioen dat via de werkgever of een verplichte beroepsregeling wordt opgebouwd."], ["De nulde pijler", "Het begrip 'nulde pijler' wordt soms informeel gebruikt, maar een individuele lijfrente valt in de derde pijler."]], "1h.3"],
["Hoe wordt de AOW in hoofdzaak gefinancierd?", [["Via een omslagstelsel: werkenden betalen voor de huidige AOW'ers, aangevuld met een rijksbijdrage", "De AOW-premie van nu financiert de uitkeringen van nu; omdat de premie niet toereikend is, vult het Rijk aan uit belastinggeld."], ["Via kapitaaldekking: iedere verzekerde spaart vanaf zijn 17e een eigen AOW-vermogen op bij de SVB", "Kapitaaldekking hoort bij de tweede en derde pijler; voor de AOW wordt geen individueel vermogen opgebouwd."], ["Via premies die werkgevers en werknemers afdragen aan een bedrijfstakpensioenfonds, dat de AOW uitkeert", "Bedrijfstakpensioenfondsen voeren tweedepijlerpensioen uit, niet de AOW."], ["Volledig uit de opbrengst van het pensioenvermogen van de SVB", "De SVB voert de AOW uit, maar beheert geen pensioenvermogen waaruit de AOW wordt betaald."]], "1h.3"],
["Wat is een kenmerkend verschil tussen de tweede en de derde pijler?", [["De tweede pijler loopt via werkgever of beroepsgroep, de derde berust op individuele keuze", "Werkgeverspensioen is gekoppeld aan het dienstverband; derdepijlerproducten sluit iemand zelf af."], ["De tweede pijler is altijd vrijwillig, de derde pijler is wettelijk verplicht", "Het is eerder andersom: deelname aan een werkgeversregeling is vaak verplicht, de derde pijler is vrijwillig."], ["De tweede pijler wordt uitgevoerd door de SVB, de derde pijler door het UWV", "De SVB voert de AOW uit en het UWV de werknemersverzekeringen; pensioenuitvoerders voeren de tweede pijler uit."], ["Over de tweede pijler wordt nooit belasting geheven, over de derde pijler altijd bij uitkering in box 1", "Voor beide pijlers geldt in de regel de omkeerregel: inleg aftrekbaar of vrijgesteld, uitkering belast."]], "1h.3"],
["Verzekeraars en andere financiële partijen maken soms onderling afspraken over hun werkwijze, bijvoorbeeld in een convenant of een gedragscode. Wat is het kenmerkende verschil tussen zulke zelfregulering en wet- en regelgeving?", [["Zelfregulering bestaat uit afspraken die de sector zelf maakt en die niet door de wetgever zijn opgelegd", "Bij zelfregulering leggen partijen zelf normen vast; naleving loopt via de sector en de afspraken, niet via de wet."], ["Zelfregulering geldt pas na goedkeuring door de Tweede Kamer en heeft dan kracht van wet", "Zelfregulering wordt niet door het parlement vastgesteld; anders zou het wetgeving zijn."], ["Zelfregulering vervangt de wet: wie een convenant naleeft, hoeft de Pensioenwet niet na te leven", "Zelfregulering komt naast de wet en ontslaat niemand van wettelijke verplichtingen."], ["Zelfregulering geldt alleen voor consumenten, wetgeving alleen voor werkgevers", "Het verschil zit in wie de regels vaststelt, niet in voor wie ze gelden."]], "1a.2"],
["In welke wet zijn de taken en bevoegdheden van DNB en de AFM bij het toezicht op pensioenfondsen in de eerste plaats vastgelegd?", [["In de Pensioenwet", "De Pensioenwet regelt het toezicht van DNB en de AFM op pensioenfondsen."], ["In de Wet op het financieel toezicht", "De Wft regelt het toezicht op onder meer verzekeraars, PPI's en adviseurs, maar het toezicht op pensioenfondsen staat in de Pensioenwet."], ["In de Algemene Ouderdomswet", "De AOW regelt het ouderdomspensioen van de eerste pijler, niet het toezicht op pensioenfondsen."], ["In de Wet op de ondernemingsraden", "De WOR regelt de medezeggenschap in ondernemingen, niet het toezicht op pensioenfondsen."]], "1a.4"],
["Over welke periode bouwt iemand AOW op?", [["De 50 jaar direct voorafgaand aan de eigen AOW-leeftijd", "De opbouwperiode schuift mee met de AOW-leeftijd en begint 50 jaar voor die leeftijd."], ["Vanaf de 15e verjaardag tot de AOW-leeftijd", "Een vaste startleeftijd van 15 jaar geldt niet meer sinds de AOW-leeftijd met de levensverwachting is gaan meebewegen."], ["Vanaf de eerste werkdag tot de AOW-leeftijd", "AOW-opbouw is gebaseerd op wonen of werken in Nederland, niet op de eerste werkdag."], ["De 40 jaar direct voorafgaand aan de eigen AOW-leeftijd, gerekend per kalenderjaar", "De periode is 50 jaar; 40 jaar zou slechts 80% opleveren."]], "1h.3"],
["Fatima is 52 jaar en kwam op haar 30e vanuit een land buiten Europa naar Nederland. Daarvoor was zij nooit verzekerd voor de AOW. Sindsdien woont en werkt zij onafgebroken in Nederland en dat blijft zo. Ga uit van een AOW-leeftijd van 67 jaar, zodat de opbouwperiode op haar 17e begint. Hoeveel procent van de volledige AOW bouwt Fatima op?", [["74%", "Zij mist de 13 jaar van haar 17e tot haar 30e; 37 verzekerde jaren maal 2% geeft 74%."], ["80%", "Dit zou gelden bij 40 verzekerde jaren; Fatima komt op 37 jaar."], ["70%", "Dit zou gelden bij 35 verzekerde jaren, maar zij is 37 jaar verzekerd."], ["100%", "Een volledige AOW vraagt 50 verzekerde jaren; Fatima mist de jaren vóór haar komst."]], "1h.14"],
["Hoe is de AOW-leeftijd gekoppeld aan de levensverwachting?", [["De AOW-leeftijd stijgt met twee derde van de stijging van de levensverwachting en wordt vijf jaar vooruit vastgesteld", "Sinds de wet van 2019 telt een jaar langere levensverwachting voor acht maanden mee, en de leeftijd wordt vijf jaar van tevoren bekendgemaakt."], ["De AOW-leeftijd stijgt een-op-een mee met de stijging van de levensverwachting en wordt jaarlijks per direct aangepast door de SVB", "Een een-op-eenkoppeling gold eerder; nu is het twee derde en geldt een aankondigingstermijn van vijf jaar."], ["De AOW-leeftijd ligt wettelijk vast op 67 jaar en wordt niet meer aangepast", "Na 2024 kan de AOW-leeftijd via de koppeling met de levensverwachting verder stijgen."], ["De AOW-leeftijd wordt per cao afgesproken tussen werkgevers en vakbonden", "De AOW-leeftijd is wettelijk geregeld; cao-partijen gaan alleen over de pensioenregeling van de werkgever."]], "1h.13"],
["Waar is de hoogte van de AOW-uitkering aan gekoppeld?", [["Aan het netto minimumloon", "De AOW volgt het netto minimumloon; voor een alleenstaande en voor samenwonenden gelden verschillende percentages daarvan."], ["Aan het laatstverdiende loon van de AOW'er", "De AOW is inkomensonafhankelijk; het eigen loon speelt geen rol."], ["Aan de dekkingsgraad van de pensioenfondsen", "De dekkingsgraad is van belang voor tweedepijlerpensioenen, niet voor de AOW."], ["Aan het gemiddelde loon over de hele loopbaan", "Een middelloonsystematiek komt voor in werkgeversregelingen, niet bij de AOW."]], "1h.3"],
["Een logistiek bedrijf wordt overgenomen door een groter transportbedrijf. Alle 40 werknemers, onder wie planner Youssef (34), gaan mee over naar de nieuwe werkgever. De oude werkgever had een pensioenregeling bij een verzekeraar. De nieuwe werkgever biedt zijn eigen personeel al een andere pensioenregeling aan en wil die ook voor de nieuwe collega's gebruiken. Youssef vraagt of zijn oude pensioenregeling gewoon doorloopt. Wat is juist bij deze overgang van onderneming?", [["Zijn arbeidsvoorwaarden gaan over, maar voor pensioen geldt een uitzondering als de nieuwe werkgever een eigen regeling aanbiedt", "Bij overgang van onderneming gaan de rechten uit de arbeidsovereenkomst over; de pensioenregeling niet als de verkrijger zelf een pensioenregeling aan de werknemers aanbiedt."], ["De nieuwe werkgever moet de oude pensioenregeling altijd ongewijzigd voortzetten, net als alle andere arbeidsvoorwaarden van Youssef", "Voor pensioen kent de overgang van onderneming juist een uitzondering."], ["Bij een overgang van onderneming eindigen alle arbeidsovereenkomsten en moet Youssef opnieuw solliciteren", "De arbeidsovereenkomsten gaan bij een overgang van onderneming van rechtswege over."], ["Youssef moet zijn opgebouwde pensioen bij de overgang laten afkopen, omdat de oude regeling stopt", "Het al opgebouwde pensioen blijft premievrij bestaan of kan worden overgedragen; afkoop is in beginsel niet toegestaan."]], "1b.6"],
["Speelt het vermogen of het overige inkomen van een AOW-gerechtigde een rol bij de hoogte van de AOW?", [["Nee, de AOW is een volksverzekering zonder inkomens- of vermogenstoets", "De hoogte hangt af van het aantal verzekerde jaren en de leefsituatie, niet van inkomen of vermogen."], ["Ja, bij een vermogen boven de vermogensgrens van de bijstand wordt de AOW naar rato gekort", "Een vermogenstoets bestaat bij de bijstand, niet bij de AOW."], ["Ja, een werkgeverspensioen wordt met de AOW verrekend", "De AOW wordt niet verrekend met een werkgeverspensioen; wel houdt de werkgeversregeling vaak rekening met de AOW via de franchise."], ["Alleen het inkomen van de partner wordt meegeteld", "Inkomen van de partner beïnvloedt de AOW niet; alleen de leefsituatie (alleenstaand of samenwonend) telt."]], "1h.3"],
["Wat wordt bedoeld met het Anw-hiaat?", [["Het inkomensgat bij overlijden doordat de Anw niet of beperkt uitkeert en het partnerpensioen dat niet opvangt", "Door de strenge voorwaarden en de inkomenstoets van de Anw kan de nabestaande inkomen tekortkomen; dat gat heet het Anw-hiaat."], ["Het verschil tussen de AOW voor alleenstaanden en voor samenwonenden", "Dat verschil heeft niets met de Anw te maken; het gaat om de AOW-leefsituatie."], ["De periode tussen het einde van de WW-uitkering en de ingangsdatum van de AOW, waarin alleen bijstand mogelijk is", "Dat is een werkloosheidsgat; het Anw-hiaat gaat over overlijden van een partner."], ["Het tekort aan AOW-opbouw door jaren in het buitenland", "Dat is een AOW-gat door ontbrekende verzekerde jaren, geen Anw-hiaat."]], "1c.11"],
["Hoe kan het Anw-hiaat worden afgedekt?", [["Met een Anw-hiaatverzekering of -pensioen, vaak via de pensioenuitvoerder, of een overlijdensrisicoverzekering", "Deze voorzieningen keren uit bij overlijden van de partner en vullen zo het ontbrekende inkomen aan."], ["Met een aanvraag voor vrijwillige AOW-verzekering bij de SVB, die bij overlijden een Anw-aanvulling uitkeert", "Vrijwillige AOW-verzekering vult AOW-gaten aan, niet het inkomensverlies bij overlijden."], ["Met een hoog-laagconstructie in het ouderdomspensioen, waardoor de partner al vóór de pensioendatum een hogere uitkering krijgt", "Een hoog-laagconstructie regelt de hoogte van het eigen ouderdomspensioen en dekt het overlijdensrisico niet."], ["Met een WW-uitkering voor de nabestaande", "Overlijden van een partner geeft geen recht op WW; de WW gaat over werkloosheid."]], "1i.8"],
["Sanne is 38 jaar en woonde ongehuwd samen met Tim, met wie zij een samenlevingscontract had. Zij hebben geen kinderen. Sanne werkt fulltime als verpleegkundige en is niet arbeidsongeschikt. Tim overlijdt onverwacht aan een hartstilstand. Heeft Sanne recht op een Anw-nabestaandenuitkering?", [["Nee: zij heeft geen kind onder 18, is niet ten minste 45% arbeidsongeschikt en is niet vóór 1950 geboren", "Voor de Anw moet een nabestaande aan een van deze toegangsvoorwaarden voldoen; Sanne voldoet aan geen enkele."], ["Ja, omdat ieder die een gezamenlijke huishouding met de overledene voerde, recht heeft op een Anw-uitkering", "Een gezamenlijke huishouding is wel nodig, maar daarnaast moet aan een van de toegangsvoorwaarden zijn voldaan."], ["Nee, omdat ongehuwd samenwonenden nooit onder de Anw vallen, ook niet met een samenlevingscontract", "Ongehuwd samenwonenden met een gezamenlijke huishouding kunnen wel onder de Anw vallen."], ["Ja, maar alleen gedurende het eerste jaar na het overlijden, als overbruggingsuitkering van de SVB", "Zo'n algemene overbruggingsuitkering van een jaar bestaat in de Anw niet."]], "1h.16"],
["Wanneer eindigt een Anw-nabestaandenuitkering in elk geval?", [["Bij het bereiken van de AOW-leeftijd", "Vanaf de AOW-leeftijd heeft de nabestaande recht op AOW en stopt de Anw-uitkering."], ["Na precies vijf jaar uitkering", "De Anw kent geen vaste maximale duur van vijf jaar."], ["Zodra de nabestaande 50 jaar wordt", "Een leeftijd van 50 jaar is geen eindmoment van de Anw."], ["Bij de eerste salarisverhoging van de nabestaande", "Inkomen kan de uitkering verlagen via de inkomenstoets, maar een salarisverhoging beëindigt het recht niet automatisch."]], "1h.16"],
["Wat is het verschil tussen partnerpensioen op opbouwbasis en op risicobasis?", [["Bij opbouwbasis blijft de aanspraak na uitdiensttreding bestaan; bij risicobasis is er alleen dekking tijdens de deelneming (plus eventuele uitloop)", "Risicobasis werkt als een overlijdensrisicoverzekering: er wordt niets opgebouwd dat na einde deelneming overblijft."], ["Bij risicobasis wordt een hoger kapitaal opgebouwd dan bij opbouwbasis, dat bij uitdiensttreding via waardeoverdracht naar de nieuwe uitvoerder gaat", "Bij risicobasis wordt geen kapitaal opgebouwd; de premie betaalt alleen de dekking."], ["Bij opbouwbasis is de dekking pas na tien jaar deelneming geldig; bij risicobasis direct vanaf de eerste werkdag", "Bij opbouwbasis groeit de aanspraak per deelnemingsjaar, er is geen wachttijd van tien jaar."], ["Er is geen verschil; het zijn twee namen voor hetzelfde", "Het verschil is wezenlijk, vooral bij baanwisseling: op risicobasis kan de dekking vervallen."]], "1i.6"],
["Pieter (41) werkt als monteur bij een installatiebedrijf en heeft daar een partnerpensioen op risicobasis. Hij woont samen met Eva en zij hebben een zoon van 6. Pieter neemt ontslag en gaat als zzp'er verder. Hij gaat ervan uit dat Eva bij zijn overlijden het partnerpensioen van zijn oude werkgever krijgt. Waarop moet de adviseur Pieter wijzen?", [["Dat de partnerpensioendekking na een eventuele uitloop vervalt en hij zijn overlijdensrisico zelf moet regelen", "Op risicobasis eindigt de dekking met de deelneming; als zzp'er moet hij het nabestaandenrisico zelf afdekken, bijvoorbeeld met een overlijdensrisicoverzekering."], ["Dat Eva levenslang het volledige partnerpensioen behoudt, ook als hij na zijn ontslag geen enkele premie meer betaalt", "Bij risicobasis blijft na het einde van de deelneming geen aanspraak bestaan."], ["Dat het partnerpensioen automatisch overgaat naar de Anw, die Eva bij zijn overlijden een aanvulling geeft", "De Anw is een aparte volksverzekering met eigen voorwaarden en neemt geen partnerpensioen over."], ["Dat hij het partnerpensioen bij uitdiensttreding kan laten afkopen en het bedrag in een lijfrente kan storten", "Bij risicobasis is er geen opgebouwde waarde die afgekocht kan worden."]], "1c.11"],
["Wat houdt uitruil van partnerpensioen naar ouderdomspensioen in?", [["De deelnemer ruilt (een deel van) het partnerpensioen in voor een hoger ouderdomspensioen, met schriftelijke toestemming van de partner", "Omdat de partner zijn aanspraak verliest, vereist de Pensioenwet schriftelijke instemming van die partner."], ["De partner ruilt zijn eigen ouderdomspensioen in voor een hoger partnerpensioen bij overlijden van de deelnemer", "Uitruil gaat over de rechten binnen de regeling van de deelnemer, niet over het eigen pensioen van de partner."], ["De deelnemer ruilt partnerpensioen in voor een hoger ouderdomspensioen zonder dat de partner betrokken hoeft te worden, mits hij dit vóór de pensioendatum meldt", "Juist omdat de partner rechten verliest, is zijn schriftelijke toestemming vereist."], ["De werkgever beslist eenzijdig om het partnerpensioen om te zetten", "Uitruil is een keuzerecht van de deelnemer, met instemming van de partner, geen werkgeversbesluit."]], "1g.13"],
["Wat is het doel van een wezenpensioen?", [["Een uitkering voor kinderen van een overleden deelnemer tot een in de regeling bepaalde leeftijd", "Het wezenpensioen ondersteunt kinderen financieel na overlijden van de ouder die deelnemer was."], ["Een levenslange uitkering voor de kinderen van een deelnemer, ingaand op de pensioendatum van de deelnemer", "Het wezenpensioen is tijdelijk en eindigt op de leeftijd die de regeling bepaalt."], ["Een aanvulling op de kinderbijslag zolang de deelnemer leeft", "Het wezenpensioen keert pas uit na overlijden van de deelnemer."], ["Een uitkering aan de ex-partner van de deelnemer na scheiding", "Rechten van een ex-partner lopen via verevening en het bijzonder partnerpensioen, niet via het wezenpensioen."]], "1i.5"],
["Wie geldt als partner voor het partnerpensioen van een ongehuwd samenwonende deelnemer?", [["Dat bepaalt het pensioenreglement; vaak is een samenlevingscontract of aanmelding bij de uitvoerder vereist", "Gehuwden en geregistreerd partners zijn doorgaans automatisch partner; voor samenwoners stelt de regeling eigen voorwaarden."], ["Iedereen die ten minste zes maanden op hetzelfde adres in de BRP staat ingeschreven, ongeacht het reglement", "Alleen inschrijving op hetzelfde adres is meestal niet voldoende; de regeling bepaalt de voorwaarden."], ["Ongehuwd samenwonenden kunnen nooit partnerpensioen krijgen", "Veel regelingen kennen wel partnerpensioen voor samenwoners, mits aan de voorwaarden is voldaan."], ["Alleen een partner met wie de deelnemer kinderen heeft, mits het ouderschap juridisch is erkend", "Kinderen zijn geen algemene voorwaarde voor het partnerbegrip in pensioenregelingen."]], "1i.5"],
["Op welk pensioen ziet de standaardverevening van de Wet verevening pensioenrechten bij scheiding?", [["Het ouderdomspensioen opgebouwd tijdens het huwelijk of geregistreerd partnerschap", "Alleen de opbouw tijdens de huwelijksperiode wordt verevend; opbouw daarvoor of daarna niet."], ["Al het ouderdomspensioen dat de deelnemer ooit heeft opgebouwd, ook vóór het huwelijk", "Opbouw van voor het huwelijk en na de scheiding valt buiten de verevening."], ["De AOW van beide ex-partners", "De AOW is een persoonlijk recht en wordt niet verevend."], ["Het partnerpensioen dat tijdens het huwelijk is opgebouwd", "Het opgebouwde partnerpensioen wordt niet verevend; daarvoor krijgt de ex-partner het bijzonder partnerpensioen."]], "1h.18"],
["Wat is het bijzonder partnerpensioen?", [["Het tot de scheiding opgebouwde partnerpensioen dat na de scheiding bestemd blijft voor de ex-partner", "Bij scheiding behoudt de ex-partner een recht op het tot dan toe opgebouwde partnerpensioen."], ["Een extra partnerpensioen dat de uitvoerder na de scheiding toekent aan een nieuwe partner van de deelnemer", "Een nieuwe partner krijgt hooguit partnerpensioen over latere opbouw; het bijzonder partnerpensioen is voor de ex."], ["Een tijdelijk partnerpensioen tot de AOW-leeftijd van de partner", "Het bijzonder partnerpensioen is niet per definitie tijdelijk en is niet gekoppeld aan de AOW-leeftijd."], ["Het deel van het ouderdomspensioen dat de ex-partner via verevening krijgt", "Het verevende ouderdomspensioen en het bijzonder partnerpensioen zijn twee verschillende rechten."]], "1h.18"],
["Wat is het verschil tussen verevening en conversie bij scheiding?", [["Bij conversie krijgt de ex-partner een zelfstandig pensioenrecht; bij verevening blijft de uitbetaling afhankelijk van het leven van de deelnemer", "Bij conversie worden de rechten definitief gesplitst; bij verevening stopt de betaling aan de ex in beginsel als de deelnemer overlijdt."], ["Conversie is de wettelijke standaard bij scheiding; verevening moet apart worden afgesproken in huwelijkse voorwaarden of een echtscheidingsconvenant", "Het is andersom: verevening is de standaard, voor conversie moeten beide ex-partners en de uitvoerder meewerken."], ["Bij verevening wordt het pensioen direct afgekocht en uitgekeerd; bij conversie wordt het pas op de pensioendatum gesplitst", "Verevening leidt tot een periodieke uitkering vanaf de pensioendatum, niet tot afkoop."], ["Er is geen verschil; beide termen staan voor gelijke verdeling", "Beide gaan over verdeling, maar het verschil in zelfstandigheid van het recht is wezenlijk."]], "1h.18"],
["Mark en Lotte zijn na twaalf jaar huwelijk gescheiden. Mark heeft in die jaren ouderdomspensioen opgebouwd bij het pensioenfonds van zijn werkgever. In de drukte rond de scheiding hebben zij het formulier voor de pensioenuitvoerder laten liggen. Pas drie jaar na de inschrijving van de scheiding melden zij die alsnog bij het fonds. Wat is daarvan het gevolg voor Lotte?", [["De uitvoerder hoeft haar niet rechtstreeks uit te betalen; zij moet haar deel bij Mark zelf zien te krijgen", "Na de meldtermijn van twee jaar behoudt Lotte haar recht op verevening, maar dan tegenover Mark en niet meer rechtstreeks tegenover de uitvoerder."], ["Lotte verliest elk recht op verevening, omdat de wettelijke meldtermijn van twee jaar is verstreken", "Het recht op verevening blijft bestaan; alleen de rechtstreekse uitbetaling door de uitvoerder vervalt."], ["De uitvoerder verevent alsnog automatisch en rechtstreeks, omdat er voor de melding geen wettelijke termijn geldt", "Er geldt wel een termijn van twee jaar voor rechtstreekse uitbetaling door de uitvoerder."], ["Mark moet de uitvoerder een boete betalen voor de late melding", "De wet kent voor late melding geen boete; het gevolg zit in de wijze van uitbetaling."]], "1h.18"],
["Esther (45) en Ruud (47) woonden vijftien jaar ongehuwd samen. Zij hadden een samenlevingscontract, maar geen huwelijk of geregistreerd partnerschap. Ruud bouwde in die jaren een flink ouderdomspensioen op bij zijn werkgever, Esther werkte parttime en bouwde weinig op. Nu gaan zij uit elkaar. Geldt de Wet verevening pensioenrechten bij scheiding (Wvps) voor het pensioen van Ruud?", [["Nee, de Wvps geldt alleen bij huwelijk of geregistreerd partnerschap; verdeling kan via eigen afspraken", "Ongehuwd samenwonenden vallen niet onder de Wvps; zij kunnen een verdeling wel in hun samenlevingscontract afspreken."], ["Ja, de Wvps geldt voor iedereen die een gezamenlijke huishouding voerde en op hetzelfde adres stond", "De Wvps is gekoppeld aan huwelijk en geregistreerd partnerschap, niet aan samenwonen."], ["Ja, maar alleen als zij samen kinderen hebben", "Het hebben van kinderen maakt de Wvps niet van toepassing."], ["Ja, omdat zij langer dan vijf jaar samenwoonden en een samenlevingscontract hadden", "Duur van het samenwonen of een samenlevingscontract maakt de Wvps niet van toepassing."]], "1h.18"],
["Kunnen echtgenoten afwijken van de standaardverevening van de Wvps?", [["Ja, via huwelijkse voorwaarden of een echtscheidingsconvenant kunnen zij anders verdelen of verevening uitsluiten", "De Wvps is de standaard, maar partijen kunnen schriftelijk iets anders overeenkomen."], ["Nee, de gelijke verdeling is dwingend recht; alleen de rechter kan bij de echtscheidingsuitspraak daarvan afwijken", "Afwijken is mogelijk via huwelijkse voorwaarden of een convenant."], ["Alleen met toestemming van De Nederlandsche Bank", "DNB houdt toezicht op uitvoerders en beslist niet over afspraken tussen ex-partners."], ["Alleen als de pensioenuitvoerder daartoe zelf besluit", "De afspraak ligt bij de echtgenoten zelf; de uitvoerder voert hun keuze uit."]], "1h.18"],
["Tussen welke partijen wordt de pensioenovereenkomst gesloten?", [["Tussen de werkgever en de werknemer", "De pensioenovereenkomst is de afspraak over pensioen als onderdeel van de arbeidsvoorwaarden."], ["Tussen de werkgever en de pensioenuitvoerder", "Dat is de uitvoeringsovereenkomst, niet de pensioenovereenkomst."], ["Tussen de werknemer en de pensioenuitvoerder", "De relatie tussen uitvoerder en werknemer is vastgelegd in het pensioenreglement."], ["Tussen de werknemer en De Nederlandsche Bank", "DNB is toezichthouder en geen partij bij een pensioenovereenkomst."]], "1i.1"],
["Hoe heet de overeenkomst tussen de werkgever en de pensioenuitvoerder over de uitvoering van de pensioenregeling?", [["De uitvoeringsovereenkomst", "Daarin leggen werkgever en uitvoerder onder meer vast hoe de premie wordt betaald en welke informatie wordt uitgewisseld."], ["Het pensioenreglement", "Het pensioenreglement beschrijft de rechten en plichten tussen uitvoerder en deelnemer."], ["De pensioenovereenkomst", "De pensioenovereenkomst sluit de werkgever met de werknemer."], ["Het uitvoeringsreglement", "Een uitvoeringsreglement wordt gebruikt bij verplichte deelneming in een bedrijfstakpensioenfonds, maar de algemene term is uitvoeringsovereenkomst."]], "1i.1"],
["Wat houdt de onderbrengingsplicht van de Pensioenwet in?", [["De werkgever moet de pensioenovereenkomst onderbrengen bij een pensioenfonds, pensioenverzekeraar of PPI", "Zo staat het pensioenvermogen los van het risico van de onderneming."], ["De werkgever moet iedere werknemer een pensioenregeling aanbieden", "De Pensioenwet verplicht niet tot het aanbieden van pensioen; een verplichting kan wel voortvloeien uit een cao of verplichtstelling."], ["De werknemer moet zijn pensioen zelf bij een verzekeraar onderbrengen", "De plicht rust op de werkgever, niet op de werknemer."], ["De werkgever moet het pensioenvermogen op een geblokkeerde bankrekening van de onderneming zetten, gescheiden van het werkkapitaal", "Pensioenvermogen binnen de eigen onderneming houden is juist niet toegestaan voor werknemers."]], "1g.8"],
["Is een werkgever wettelijk verplicht om zijn werknemers een pensioenregeling aan te bieden?", [["Nee, tenzij een verplichtstelling van een bedrijfstakpensioenfonds of een cao hem daartoe verplicht", "De Pensioenwet regelt wat geldt als er een pensioenregeling is, maar kent geen algemene plicht om er een aan te bieden."], ["Ja, iedere werkgever met personeel moet pensioen aanbieden", "Een algemene pensioenplicht voor werkgevers bestaat in Nederland niet."], ["Ja, maar alleen voor werknemers met een vast contract", "Ook voor vaste werknemers bestaat geen algemene wettelijke plicht."], ["Nee, en een werkgever kan ook niet via een verplichtstelling van een bedrijfstakpensioenfonds worden verplicht", "Via een verplichtstelling kan deelneming in een bedrijfstakpensioenfonds wel verplicht zijn."]], "1g.8"],
["Welke omschrijving past bij een uitkeringsovereenkomst?", [["De werkgever zegt een bepaalde pensioenuitkering toe, bijvoorbeeld op basis van middelloon", "Bij een uitkeringsovereenkomst staat de hoogte van de uitkering centraal en is de benodigde premie variabel."], ["De werkgever zegt een vaste premie toe en de uitkering hangt af van het rendement", "Dat is een premieovereenkomst."], ["De werkgever zegt een vast kapitaal op de pensioendatum toe waarmee een uitkering wordt aangekocht", "Dat is een kapitaalovereenkomst."], ["De werknemer bepaalt zelf jaarlijks hoeveel premie de werkgever betaalt", "Zo werkt geen van de wettelijke pensioenovereenkomsten."]], "1h.2"],
["Wat kenmerkt een kapitaalovereenkomst?", [["Er wordt een vast kapitaal op de pensioendatum toegezegd, waarmee een uitkering wordt aangekocht", "Het kapitaal ligt vast; de hoogte van de uitkering hangt af van de inkooptarieven op dat moment."], ["Er wordt een vaste levenslange uitkering toegezegd", "Een toegezegde uitkering hoort bij de uitkeringsovereenkomst."], ["Er wordt alleen een vaste premie toegezegd zonder enige garantie", "Dat is kenmerkend voor de premieovereenkomst."], ["Er wordt een vast kapitaal toegezegd dat op de pensioendatum vrij opneembaar als bedrag ineens wordt uitgekeerd", "Het kapitaal moet worden omgezet in een pensioenuitkering en is niet vrij opneembaar."]], "1h.3"],
["Bij welke pensioenovereenkomst ligt het beleggingsrisico in beginsel bij de deelnemer?", [["Bij de premieovereenkomst", "De werkgever betaalt een afgesproken premie; de uiteindelijke uitkering hangt af van het beleggingsresultaat."], ["Bij de uitkeringsovereenkomst", "Daar is een uitkering toegezegd en ligt het risico vooral bij de uitvoerder en het collectief."], ["Bij de kapitaalovereenkomst", "Het kapitaal ligt vast; het beleggingsrisico tijdens de opbouw ligt niet bij de deelnemer."], ["Bij geen enkele overeenkomst; dat risico ligt altijd bij de werkgever", "Bij een premieovereenkomst draagt de werkgever het beleggingsrisico juist niet."]], "1f.2"],
["Wat is waardeoverdracht?", [["Het meenemen van de waarde van opgebouwde pensioenaanspraken naar de uitvoerder van de nieuwe werkgever", "De gewezen deelnemer kan zo zijn pensioen bundelen bij de uitvoerder van de nieuwe werkgever."], ["Het overdragen van pensioen aan de ex-partner na scheiding", "Verdeling bij scheiding verloopt via verevening of conversie, niet via waardeoverdracht."], ["Het uitkeren van de waarde van het pensioen als bedrag ineens bij uitdiensttreding, waarover loonheffing wordt ingehouden", "Dat is afkoop; bij waardeoverdracht blijft het geld bestemd voor pensioen."], ["Het omzetten van pensioen in een lijfrente bij een bank", "Waardeoverdracht gaat naar de pensioenuitvoerder van de nieuwe werkgever, niet naar een bancaire lijfrente."]], "1h.4"],
["Wanneer is individuele waardeoverdracht tijdelijk niet toegestaan?", [["Als de dekkingsgraad van de overdragende of de ontvangende pensioenuitvoerder onder de 100% ligt", "Zo wordt voorkomen dat een tekort wordt meegenomen of dat achterblijvers worden benadeeld."], ["Als de werknemer korter dan tien jaar bij de oude werkgever heeft gewerkt en dus nog geen onvoorwaardelijke aanspraak heeft", "Er geldt geen minimale diensttijd van tien jaar voor waardeoverdracht."], ["Als de nieuwe werkgever in een andere bedrijfstak actief is", "Een andere bedrijfstak is geen grond om waardeoverdracht te weigeren."], ["Als de werknemer ouder is dan 55 jaar", "Er geldt geen leeftijdsgrens van 55 jaar voor waardeoverdracht."]], "1h.4"],
["Wat is het doel van de regels voor automatische waardeoverdracht van kleine pensioenen?", [["Voorkomen dat deelnemers veel kleine, versnipperde pensioenen bij verschillende uitvoerders houden", "Kleine pensioenen worden zo samengevoegd bij de uitvoerder van de nieuwe werkgever, zodat ze niet verloren gaan of worden afgekocht."], ["Kleine pensioenen bij uitdiensttreding direct contant uitbetalen, zodat de deelnemer er zelf over kan beschikken", "De regeling is juist bedoeld om kleine pensioenen voor de oude dag te behouden."], ["Kleine pensioenen overbrengen naar de AOW", "Tweedepijlerpensioen kan niet naar de AOW worden overgebracht."], ["Kleine pensioenen laten omzetten in een lijfrente op naam van de werkgever", "Een pensioen wordt niet omgezet in een lijfrente op naam van de werkgever."]], "1g.4"],
["Aan welke eisen moet pensioeninformatie volgens de Pensioenwet in ieder geval voldoen?", [["Correct, duidelijk en evenwichtig", "De informatie moet ook begrijpelijk en tijdig zijn, zodat de deelnemer er een beslissing op kan baseren."], ["Volledig, juridisch en uitputtend", "Uitputtende juridische informatie gaat juist ten koste van de begrijpelijkheid."], ["Uitsluitend schriftelijk en op papier", "Pensioeninformatie mag ook elektronisch worden verstrekt."], ["Vooraf goedgekeurd door de AFM", "De AFM houdt toezicht op pensioencommunicatie, maar keurt informatie niet vooraf goed."]], "2a.5"],
["Wat is het Uniform Pensioenoverzicht (UPO) voor een actieve deelnemer?", [["Een periodiek overzicht van de uitvoerder met opgebouwde en te bereiken pensioenaanspraken in vaste opzet", "Doordat alle uitvoerders dezelfde opzet volgen, zijn overzichten onderling vergelijkbaar."], ["Een overzicht dat de adviseur verplicht moet opstellen bij elk pensioenadvies en jaarlijks aan de klant moet sturen", "Het UPO komt van de pensioenuitvoerder, niet van de adviseur."], ["Een jaarlijks overzicht van de SVB met alleen de AOW", "De SVB informeert over de AOW; het UPO gaat over het pensioen bij de uitvoerder."], ["Een contract waarin de werknemer zijn keuzes vastlegt", "Het UPO is een informatieoverzicht, geen contract."]], "1g.13"],
["Kees (44) werkte negen jaar als logistiek medewerker bij een groothandel en bouwde pensioen op bij het pensioenfonds van die bedrijfstak. Vorig jaar stapte hij over naar een webwinkel met een eigen pensioenregeling bij een verzekeraar. Hij heeft zijn oude pensioen niet laten overdragen, zodat er bij het oude fonds een premievrije aanspraak staat. Kees vraagt hoe hij nu bij dat fonds bekendstaat. Wat is juist?", [["Als gewezen deelnemer", "Een gewezen deelnemer heeft bij beëindiging van de deelneming een premievrije aanspraak achtergelaten bij de uitvoerder."], ["Als pensioengerechtigde", "Een pensioengerechtigde ontvangt al een pensioenuitkering; Kees is nog niet met pensioen."], ["Als aspirant-deelnemer", "Een aspirant-deelnemer moet nog gaan deelnemen; Kees heeft juist al deelgenomen."], ["Als actieve deelnemer", "Kees bouwt bij het oude fonds niets meer op, dus hij is daar geen actieve deelnemer meer."]], "1h.3"],
["Welke twee typen premieregelingen kent de Wet toekomst pensioenen?", [["De solidaire premieregeling en de flexibele premieregeling", "In het nieuwe stelsel worden pensioenen opgebouwd in een van deze twee regelingen."], ["De middelloonregeling en de eindloonregeling", "Dit zijn varianten van de uitkeringsovereenkomst die in het nieuwe stelsel verdwijnen."], ["De kapitaalregeling en de beschikbare-premieregeling nieuwe stijl", "Deze termen horen bij het oude stelsel en zijn niet de twee nieuwe Wtp-contracten."], ["De collectieve regeling en de bancaire regeling", "Een 'bancaire regeling' bestaat niet als contractvorm onder de Wtp."]], "1h.13"],
["Wat is een kenmerk van de solidaire premieregeling?", [["Er wordt collectief belegd, met een solidariteitsreserve om schokken te dempen en risico's te delen", "Het rendement wordt via vaste regels aan leeftijdsgroepen toegedeeld; de solidariteitsreserve zorgt voor extra risicodeling."], ["Iedere deelnemer kiest zelf zijn beleggingsmix en draagt het volledige risico, zonder collectieve reserve", "Dat past meer bij de flexibele premieregeling."], ["De uitkering is gegarandeerd door de werkgever", "In de solidaire premieregeling is geen uitkering gegarandeerd; er is een pensioenambitie."], ["Er wordt niet belegd; het pensioen groeit alleen met de premies", "Ook in de solidaire premieregeling wordt belegd."]], "1f.3"],
["Wat is een kenmerk van de flexibele premieregeling?", [["De deelnemer heeft een eigen pensioenvermogen dat volgens een lifecycle wordt belegd, met keuzemogelijkheden", "Het risico wordt afgestemd op de leeftijd en het risicoprofiel van de deelnemer."], ["Alle deelnemers delen één collectief vermogen zonder persoonlijke toedeling, met een solidariteitsreserve voor schokken", "In beide Wtp-regelingen heeft de deelnemer een persoonlijk pensioenvermogen."], ["De werkgever kiest elk jaar opnieuw de hoogte van de uitkering", "De uitkering hangt af van het opgebouwde vermogen, niet van een jaarlijkse werkgeverskeuze."], ["De deelnemer mag het vermogen op elk moment vrij opnemen", "Pensioenvermogen blijft bestemd voor pensioen en is niet vrij opneembaar."]], "1f.1"],
["Wat betekent het afschaffen van de doorsneesystematiek onder de Wtp?", [["Iedere deelnemer krijgt een leeftijdsonafhankelijke premie, waardoor jongeren relatief meer opbouwen dan voorheen", "Voorheen gold een gelijk opbouwpercentage tegen een gelijke premie; nu levert de premie per leeftijd een eigen opbouw op."], ["De premie wordt hoger naarmate de deelnemer ouder wordt, waardoor oudere werknemers juist meer pensioen opbouwen", "Een stijgende premie (staffel) was juist kenmerkend voor oude premieregelingen; de Wtp gaat uit van een vlakke premie."], ["Iedere deelnemer bouwt jaarlijks hetzelfde percentage pensioen op over zijn pensioengrondslag, ongeacht zijn leeftijd", "Dat was juist de doorsneesystematiek die verdwijnt."], ["De AOW wordt voortaan door pensioenfondsen uitgekeerd", "De AOW blijft een volksverzekering via de SVB."]], "1h.13"],
["Waarom moeten sociale partners bij de transitie naar het nieuwe stelsel aandacht besteden aan compensatie?", [["Omdat vooral middelbare en oudere werknemers nadeel kunnen hebben van de overgang naar een vlakke premie", "Zij hebben in hun jonge jaren relatief weinig opgebouwd en bouwen bij een vlakke premie later minder op dan onder de doorsneesystematiek."], ["Omdat jongeren door de Wtp een lagere AOW krijgen", "De Wtp verandert de AOW niet."], ["Omdat werkgevers na de transitie geen premie meer hoeven te betalen en werknemers de volledige premie zelf dragen", "Werkgevers blijven premie betalen in het nieuwe stelsel."], ["Omdat gepensioneerden hun hele uitkering moeten terugbetalen", "Gepensioneerden hoeven niets terug te betalen."]], "1h.13"],
["Wat wordt bij de transitie bedoeld met invaren?", [["Het omzetten van bestaande, opgebouwde pensioenaanspraken en -rechten naar de nieuwe premieregeling", "Na invaren worden ook oude rechten in het nieuwe contract voortgezet als persoonlijk pensioenvermogen of uitkering."], ["Het overstappen van een werknemer naar een andere werkgever, waarbij zijn pensioen naar de nieuwe uitvoerder gaat", "Dat leidt hooguit tot waardeoverdracht, niet tot invaren."], ["Het afkopen van alle pensioenen bij de overstap", "Invaren betekent juist dat de rechten blijven bestaan in het nieuwe contract."], ["Het aanmelden van nieuwe werknemers bij een pensioenfonds", "Dat is aanmelding van deelnemers, geen invaren."]], "1h.4"],
["Wat is de uiterste datum waarop pensioenregelingen moeten zijn overgegaan naar het nieuwe stelsel van de Wtp?", [["1 januari 2028", "De transitieperiode van de Wtp loopt tot uiterlijk 1 januari 2028."], ["1 januari 2027", "Dat was de oorspronkelijke einddatum; deze is verschoven naar 1 januari 2028."], ["1 juli 2023", "Op 1 juli 2023 is de Wtp in werking getreden; dat is het begin, niet het einde van de transitie."], ["31 december 2029", "De transitieperiode loopt niet tot eind 2029."]], "1h.13"],
["Op welke datum is de Wet toekomst pensioenen in werking getreden?", [["1 juli 2023", "Vanaf die datum liep de transitieperiode naar het nieuwe stelsel."], ["1 januari 2022", "In 2022 lag het wetsvoorstel nog bij het parlement."], ["1 januari 2025", "Op die datum stapten sommige fondsen over, maar de wet gold al eerder."], ["1 januari 2028", "Dat is de uiterste transitiedatum, niet de datum van inwerkingtreding."]], "1h.13"],
["Jolanda (55) werkt al dertig jaar in de zorg en bouwt pensioen op bij een groot bedrijfstakpensioenfonds. Het fonds heeft besloten om de opgebouwde pensioenen in te laten varen in de nieuwe solidaire premieregeling. Jolanda heeft daar geen goed gevoel over en wil haar pensioen in de oude regeling houden. Zij vraagt haar adviseur of zij persoonlijk bezwaar kan maken tegen het invaren. Wat is juist?", [["Nee, er is geen individueel bezwaarrecht; het fondsbestuur moet de belangen evenwichtig afwegen", "De Wtp kent geen individueel bezwaarrecht tegen invaren; het bestuur moet een evenwichtige belangenafweging maken, waarbij fondsorganen worden betrokken."], ["Ja, iedere deelnemer kan binnen zes maanden na het transitiebesluit individueel schriftelijk bezwaar maken", "Zo'n individueel bezwaarrecht tegen invaren staat niet in de Wtp."], ["Ja, maar alleen deelnemers van 55 jaar en ouder, omdat zij het dichtst bij hun pensioen zitten", "Ook voor oudere deelnemers bestaat geen individueel bezwaarrecht tegen invaren."], ["Nee, maar zij kan wel eisen dat haar pensioen vóór de transitie wordt afgekocht of overgedragen", "De transitie geeft geen recht op afkoop of op een individuele overdracht om het invaren te ontlopen."]], "1h.13"],
["Hoe is het partnerpensioen vóór de pensioendatum onder de Wtp in beginsel geregeld?", [["Op risicobasis, met een maximale hoogte die is gekoppeld aan het salaris", "Daardoor hangt de dekking niet meer af van het aantal dienstjaren; de wet stelt een maximum van 50% van het salaris."], ["Op opbouwbasis, afhankelijk van het aantal dienstjaren bij de huidige werkgever", "De Wtp kiest voor risicobasis zodat de hoogte niet van de diensttijd afhangt."], ["Het partnerpensioen is onder de Wtp afgeschaft", "Het partnerpensioen blijft bestaan, maar op risicobasis."], ["Als een vast bedrag dat voor iedere deelnemer gelijk is", "De hoogte is gerelateerd aan het salaris, niet een vast bedrag."]], "1i.5"],
["Adviseur Mirjam bereidt een nieuwe pensioenregeling voor bij een bakkerij die als bv is opgericht. De bedrijfsleider wil de pensioenovereenkomst namens de bv ondertekenen en zegt dat hij 'dat soort dingen altijd regelt'. Mirjam raadpleegt het Handelsregister van de Kamer van Koophandel. Daaruit blijkt dat alleen de twee bestuurders samen bevoegd zijn de bv te vertegenwoordigen. Wat moet Mirjam doen?", [["Laten ondertekenen door de bestuurders die volgens het Handelsregister bevoegd zijn, of door iemand met hun volmacht", "Alleen wie bevoegd is de bv te vertegenwoordigen, of daarvoor een volmacht heeft, kan de bv rechtsgeldig binden."], ["Niets, een bedrijfsleider is altijd bevoegd om pensioenovereenkomsten namens de bv te tekenen", "Een bedrijfsleider is niet automatisch vertegenwoordigingsbevoegd; dat blijkt uit het Handelsregister of een volmacht."], ["De handtekening laten bevestigen door de ondernemingsraad, die de bv dan kan vertegenwoordigen", "De OR heeft medezeggenschap, maar vertegenwoordigt de bv niet."], ["De overeenkomst door de pensioenuitvoerder namens de bv laten ondertekenen", "De uitvoerder is een andere partij en kan de bv niet vertegenwoordigen."]], "1b.1"],
["Wat betekent de keuze voor een variabele pensioenuitkering in het nieuwe stelsel?", [["De uitkering kan meebewegen met beleggingsresultaten en ontwikkelingen in de levensverwachting", "Een variabele uitkering kan stijgen en dalen; schokken kunnen wel over enkele jaren worden gespreid."], ["De uitkering is gegarandeerd en stijgt jaarlijks met de inflatie", "Een variabele uitkering is juist niet gegarandeerd."], ["De deelnemer kiest zelf per maand het bedrag dat hij opneemt", "Ook een variabele uitkering is een periodieke pensioenuitkering volgens vaste regels, geen vrije opname."], ["De uitkering stopt zodra het persoonlijke pensioenvermogen op is, ongeacht de leeftijd van de gepensioneerde", "Een pensioenuitkering is in beginsel levenslang."]], "1f.5"],
["Geldt na het einde van de transitie nog een uitkeringsovereenkomst als vorm voor nieuwe pensioenopbouw?", [["Nee, nieuwe opbouw vindt dan plaats in een premieovereenkomst nieuwe stijl", "De Wtp maakt een einde aan nieuwe opbouw in uitkeringsovereenkomsten."], ["Ja, werkgevers mogen vrij kiezen tussen een uitkeringsovereenkomst en een premieovereenkomst", "Na de transitie is nieuwe opbouw in een uitkeringsovereenkomst niet meer toegestaan."], ["Ja, maar alleen voor werknemers ouder dan 50 jaar", "Er bestaat geen leeftijdsuitzondering voor nieuwe opbouw in een uitkeringsovereenkomst."], ["Ja, als de werkgever zelf garant staat voor de uitkering", "Een garantie van de werkgever maakt nieuwe opbouw in een uitkeringsovereenkomst niet mogelijk."]], "1h.13"],
["Ahmed (52) is accountmanager bij een ICT-bedrijf. Hij heeft een premieregeling met een leeftijdsafhankelijke premiestaffel, waardoor de premie voor hem ieder jaar hoger wordt. Zijn werkgever stapt over naar een premieregeling onder de Wet toekomst pensioenen, waarin nieuwe deelnemers een vlakke premie krijgen. Ahmed is bang dat zijn premie fors daalt. Wat kan voor hem gelden?", [["Werkgever en werknemers kunnen kiezen voor eerbiedigende werking, zodat zijn staffel onder voorwaarden doorloopt", "De Wtp staat toe dat bestaande deelnemers in een premieregeling met staffel die staffel onder voorwaarden houden."], ["Zijn staffel moet in alle gevallen met terugwerkende kracht naar een vlakke premie voor iedereen worden teruggedraaid", "Er is geen terugwerkende kracht en eerbiedigende werking is juist mogelijk."], ["Hij moet zelf het verschil tussen de oude en de nieuwe premie bijbetalen om zijn opbouw te behouden", "De wet legt geen bijbetalingsplicht bij de werknemer."], ["Hij verliest het pensioenvermogen dat hij in de oude premieregeling al heeft opgebouwd", "Opgebouwd vermogen blijft van de deelnemer; de overstap tast dat niet aan."]], "1h.12"],
["Hoe worden te verwachten pensioenuitkeringen in het nieuwe stelsel aan deelnemers getoond?", [["In verschillende scenario's, zoals een verwacht, een optimistisch en een pessimistisch scenario", "Zo ziet de deelnemer dat het pensioen niet vastligt en kan meebewegen met de economie."], ["Als één gegarandeerd bedrag dat bij de start van de uitkering wordt vastgezet en niet meer kan wijzigen", "In het nieuwe stelsel is de uitkering niet gegarandeerd."], ["Uitsluitend als totaalbedrag van alle betaalde premies", "Alleen ingelegde premie zegt weinig over de te verwachten uitkering."], ["Alleen als percentage van het laatstverdiende loon", "Een vervangingsratio kan helpen, maar de wettelijke communicatie werkt met scenario's."]], "1g.13"],
["Welke informatie moeten deelnemers rond de transitie in ieder geval krijgen van hun pensioenuitvoerder?", [["Persoonlijke informatie over hun pensioen vóór en na de overstap, zodat het effect zichtbaar is", "Deelnemers moeten kunnen zien wat de overstap voor hun eigen pensioen betekent."], ["Een aanbod om het pensioen af te kopen in plaats van over te stappen", "De transitie biedt geen afkoopmogelijkheid als alternatief."], ["Een verzoek om zelf een nieuwe pensioenuitvoerder te kiezen", "De keuze van de uitvoerder ligt bij werkgever en sociale partners, niet bij de deelnemer."], ["Uitsluitend algemene informatie over de wet en de transitie, zonder persoonlijke gegevens over de eigen aanspraken", "Algemene informatie is niet genoeg; juist persoonlijke informatie is belangrijk."]], "1h.13"],
["Willemijn (59) heeft een brief van haar pensioenfonds gekregen over de overstap naar het nieuwe stelsel. Daarin staat dat zij straks een persoonlijk pensioenvermogen heeft. Op een verjaardag hoort zij dat ze dat 'potje geld' later vrij kan opnemen. Zij wil daarmee op haar pensioendatum haar hypotheek aflossen. Wat is de juiste reactie van de adviseur?", [["Het vermogen blijft bestemd voor een pensioenuitkering; wel kan zij op de pensioendatum tot 10% ineens opnemen", "Ook in het nieuwe stelsel is het vermogen bedoeld voor een levenslange uitkering; vrije opname kan niet, een bedrag ineens van maximaal 10% wel."], ["Dat klopt, vanaf de pensioendatum mag zij het hele vermogen vrij opnemen als zij er box 1-belasting over betaalt", "Het pensioenvermogen kan niet vrij worden opgenomen; het moet worden omgezet in een uitkering."], ["Dat klopt, zij kan het vermogen zelfs al vóór de pensioendatum opvragen om de hypotheek af te lossen", "Voortijdige opname voor de hypotheek is niet toegestaan."], ["Het vermogen gaat bij de overstap naar de AOW, die daardoor hoger wordt", "De AOW is een aparte volksverzekering en ontvangt geen pensioenvermogen."]], "1g.5"],
["Wat is het Witteveenkader?", [["Het fiscale kader in de Wet op de loonbelasting dat de maximale fiscaal gefaciliteerde pensioenopbouw of -premie bepaalt", "Binnen dit kader geldt de omkeerregel; daarboven is de opbouw niet fiscaal gefaciliteerd."], ["Het financieel toetsingskader van DNB voor de financiële positie van pensioenfondsen, met eisen aan buffers en dekkingsgraad", "Het financieel toetsingskader van DNB gaat over buffers, niet over fiscale grenzen."], ["De regels voor pensioenverdeling bij scheiding", "Pensioenverdeling bij scheiding staat in de Wvps."], ["De regels voor de AOW-opbouw van migranten", "De AOW-opbouw is geregeld in de Algemene Ouderdomswet."]], "1g.8"],
["Wat houdt de omkeerregel in bij pensioen?", [["Premies en aanspraken zijn tijdens de opbouw onbelast of aftrekbaar; de uitkeringen zijn belast", "De belastingheffing wordt uitgesteld tot het moment van uitkeren."], ["Premies zijn belast en de uitkeringen zijn onbelast", "Die systematiek geldt bij nettopensioen en netto-lijfrente, niet bij de omkeerregel."], ["Zowel premies als uitkeringen zijn onbelast", "Volledige vrijstelling bestaat niet; de uitkering wordt belast."], ["De werkgever betaalt de belasting over de uitkering in plaats van de werknemer, als eindheffing via de loonaangifte", "De gepensioneerde betaalt zelf belasting over de pensioenuitkering."]], "1g.10"],
["Wat gebeurt er fiscaal als een pensioenregeling de grenzen van het Witteveenkader overschrijdt?", [["De regeling wordt bovenmatig en verliest haar fiscale status, waardoor de aanspraak als loon belast kan worden", "Een bovenmatige regeling is onzuiver; dat leidt tot belastingheffing bij de werknemer."], ["Alleen het bovenmatige deel wordt pas belast bij uitkering, zonder gevolgen voor de rest van de pensioenregeling", "Het gevolg is ingrijpender: de regeling verliest haar status als pensioenregeling."], ["De werkgever moet de pensioenuitvoerder een boete betalen", "Er is geen boete aan de uitvoerder; het gevolg is fiscaal."], ["Er gebeurt niets; het Witteveenkader is een richtlijn zonder gevolgen", "Overschrijding van het fiscale kader heeft wel degelijk fiscale gevolgen."]], "1g.8"],
["Wat is de franchise in een pensioenregeling?", [["Het deel van het salaris waarover geen pensioen wordt opgebouwd, omdat daar de AOW al in voorziet", "Pensioengevend salaris minus franchise is de pensioengrondslag."], ["Het maximale pensioengevende salaris waarboven geen fiscaal gefaciliteerde opbouw meer mogelijk is", "Dat is de aftoppingsgrens (het maximum pensioengevend loon), niet de franchise."], ["Het eigen risico dat de deelnemer betaalt bij arbeidsongeschiktheid", "De franchise heeft niets met arbeidsongeschiktheid te maken."], ["Het deel van de premie dat de werknemer zelf betaalt", "Dat is de werknemersbijdrage."]], "1h.3"],
["Wat verandert de Wtp aan de systematiek van het Witteveenkader?", [["De fiscale grens wordt uitgedrukt als een maximale premie in plaats van een maximaal opbouwpercentage", "Bij premieregelingen nieuwe stijl past een premiegrens beter dan een opbouwgrens."], ["Het fiscale kader vervalt volledig; elke premie is aftrekbaar", "Er blijft een fiscaal maximum gelden."], ["De omkeerregel wordt vervangen door belastingheffing in box 3", "De omkeerregel blijft bestaan; pensioen valt niet in box 3."], ["Pensioenopbouw wordt alleen nog fiscaal gefaciliteerd over het salaris tot de franchise, daarboven via nettopensioen", "De franchise is juist het deel waarover geen pensioen wordt opgebouwd."]], "1g.8"],
["Tot wanneer mag een ouderdomspensioen fiscaal gezien uiterlijk ingaan?", [["Uiterlijk vijf jaar na de AOW-leeftijd", "Uitstel van het pensioen is fiscaal toegestaan tot vijf jaar na de AOW-leeftijd."], ["Uiterlijk op de AOW-leeftijd, uitstel is niet toegestaan", "Uitstel na de AOW-leeftijd is wel mogelijk, tot een maximum."], ["Uiterlijk tien jaar na de AOW-leeftijd", "Tien jaar is langer dan fiscaal is toegestaan."], ["Er geldt geen uiterste ingangsdatum", "Er geldt wel een fiscale uiterste ingangsdatum."]], "1g.5"],
["Welk deel van de waarde van het ouderdomspensioen kan een deelnemer op de pensioeningangsdatum maximaal als bedrag ineens laten uitbetalen?", [["10%", "De deelnemer mag maximaal 10% van de waarde van zijn ouderdomspensioen op de ingangsdatum ineens opnemen."], ["25%", "25% is meer dan de wet toestaat; het maximum is 10%."], ["7,5%", "Het maximum ligt hoger, namelijk op 10%."], ["50%", "Zo'n groot deel ineens opnemen is niet toegestaan; het maximum is 10%."]], "1g.5"],
["Joke (67) gaat volgende maand met pensioen bij het pensioenfonds van de gemeente waar zij werkte. Zij is alleenstaand, huurt een appartement en ontvangt huurtoeslag. Het fonds biedt haar de mogelijkheid om een deel van haar pensioen als bedrag ineens op te nemen. Zij wil daarmee een nieuwe auto kopen. Waarop moet de adviseur haar in elk geval wijzen?", [["Het bedrag ineens is belast in box 1, kan haar huurtoeslag raken en verlaagt haar maandpensioen blijvend", "Het bedrag ineens telt mee als inkomen in het jaar van opname, wat toeslagen kan beïnvloeden, en het levenslange pensioen wordt lager."], ["Het bedrag ineens is onbelast omdat over de premie al belasting is betaald, en het raakt haar toeslag niet", "Pensioen valt onder de omkeerregel: de opname is belast en telt mee voor het toetsingsinkomen."], ["Haar maandpensioen blijft even hoog; het bedrag ineens komt erbovenop en wordt in box 3 belast", "Het bedrag ineens gaat ten koste van de periodieke uitkering en is belast in box 1."], ["Zij kan het bedrag ineens op elk moment na de pensioendatum opvragen, uiterlijk tot haar 75e", "De keuze voor een bedrag ineens moet bij ingang van het pensioen worden gemaakt."]], "1g.5"],
["Wanneer is de premie voor een lijfrente in box 1 aftrekbaar?", [["Als er een pensioentekort is, binnen de jaarruimte of reserveringsruimte", "Lijfrentepremie is alleen aftrekbaar voor zover de belastingplichtige een pensioentekort heeft."], ["Altijd volledig, ongeacht het pensioen dat al via de werkgever wordt opgebouwd", "De aftrek is beperkt tot de jaarruimte en reserveringsruimte."], ["Alleen als de lijfrente bij een pensioenfonds wordt afgesloten", "Lijfrente kan bij een verzekeraar of bank lopen; een pensioenfonds is niet vereist."], ["Alleen als de premie door de werkgever wordt betaald", "Lijfrente is juist een individuele voorziening die de klant zelf betaalt."]], "1g.10"],
["Wat wordt in risicomanagement verstaan onder de risicoacceptatiegraad (risk appetite) van een organisatie?", [["De hoeveelheid risico die een organisatie bewust wil aanvaarden om haar doelen te halen", "De risicoacceptatiegraad geeft aan hoeveel en welk risico de organisatie bewust wil lopen bij het nastreven van haar doelen."], ["De toegestane afwijking rond een vastgestelde risiconorm", "Dat is de risicotolerantie: de marge rond de gekozen norm."], ["Het totale bedrag dat een organisatie tegen risico's heeft verzekerd", "Een verzekerd bedrag zegt niets over hoeveel risico de organisatie bereid is te lopen."], ["Het totale bedrag waarvoor een organisatie zich tegen risico's heeft verzekerd bij verzekeraars", "Het aantal geïnventariseerde risico's is geen maatstaf voor de bereidheid om risico te lopen."]], "1c.6"],
["Een werkgever spreekt met zijn adviseur af dat de jaarlijkse pensioenlasten maximaal 10% van het begrote bedrag mogen afwijken. Welk begrip uit het risicomanagement past het best bij deze afspraak?", [["Risicotolerantie", "Risicotolerantie is de aanvaardbare afwijking rond een doel of norm, zoals hier 10% rond de begroting."], ["Risicobewustzijn", "Risicobewustzijn gaat over het herkennen van risico's, niet over een toegestane afwijking."], ["Ondernemingsrisicomanagement", "Ondernemingsrisicomanagement is de brede aanpak van risico's in de hele organisatie, niet een afwijkingsmarge."], ["Risicoacceptatiegraad", "De risicoacceptatiegraad gaat over hoeveel risico de organisatie in het algemeen wil lopen; de marge rond een norm is de tolerantie."]], "1c.7"],
["Wat is een fiscaal gevolg als een fiscaal gefaciliteerde lijfrente in één keer wordt afgekocht?", [["De afkoopsom is belast in box 1 en er kan revisierente verschuldigd zijn", "Omdat de premie eerder aftrekbaar was, wordt de afkoop belast en kan revisierente over de waarde worden geheven."], ["De afkoopsom is onbelast omdat het eigen spaargeld betreft dat al in box 3 werd belast", "De premie is eerder afgetrokken; de afkoopsom is daarom belast."], ["De afkoopsom valt in box 3 tegen het forfaitaire rendement", "Afkoop van een gefaciliteerde lijfrente wordt in box 1 belast."], ["Afkopen van een lijfrente is wettelijk nooit toegestaan", "Afkopen kan, maar heeft fiscale gevolgen."]], "1j.5"],
["Bij de analyse van de jaarrekening van een werkgever kijkt de adviseur naar de current ratio. Wat drukt dit kengetal uit?", [["De verhouding tussen de vlottende activa en de kortlopende schulden", "De current ratio laat zien of de onderneming haar kortlopende schulden met haar vlottende activa kan voldoen."], ["De verhouding tussen het eigen vermogen en het totale vermogen", "Dat is een solvabiliteitsratio."], ["De nettowinst als percentage van het eigen vermogen", "Dat is de rentabiliteit van het eigen vermogen (REV)."], ["De verhouding tussen de pensioenlasten en de totale loonsom", "Dat is geen standaard liquiditeitskengetal; de current ratio gaat over activa en schulden."]], "1d.2"],
["Ilse (43) is medisch specialist in loondienst bij een ziekenhuis en verdient ruim boven de aftoppingsgrens. Over het salaris boven die grens bouwt zij geen fiscaal gefaciliteerd pensioen meer op. Haar werkgever biedt daarom een vrijwillige nettopensioenregeling aan. Ilse overweegt mee te doen en vraagt hoe het fiscaal werkt. Wat is een kenmerk van het nettopensioen?", [["De inleg is niet aftrekbaar en de latere uitkering is onbelast", "Het nettopensioen wordt uit nettoloon betaald en is in box 3 vrijgesteld; de uitkering is daarom onbelast."], ["De inleg is aftrekbaar en de latere uitkering is belast in box 1", "Dat is de omkeerregel voor gewoon pensioen; het nettopensioen werkt andersom."], ["De werkgever is verplicht de volledige premie voor het nettopensioen te betalen", "Deelname is vrijwillig en wordt betaald uit het nettoloon van de werknemer."], ["Het opgebouwde vermogen telt jaarlijks mee als vermogen in box 3", "Het nettopensioen is juist vrijgesteld in box 3."]], "1g.10"],
["Waar kan een particulier een fiscaal gefaciliteerde lijfrente in de opbouwfase onderbrengen?", [["Bij een verzekeraar, of bij een bank of beleggingsinstelling via een lijfrenterekening of -beleggingsrecht", "Sinds de introductie van banksparen kan lijfrente ook bancair worden opgebouwd."], ["Uitsluitend bij een bedrijfstakpensioenfonds", "Een bedrijfstakpensioenfonds voert tweedepijlerpensioen uit, geen individuele lijfrentes."], ["Uitsluitend bij de SVB", "De SVB voert volksverzekeringen uit en biedt geen lijfrentes aan."], ["Op een gewone spaarrekening op eigen naam zonder blokkering, mits de klant het tegoed niet vóór zijn AOW-leeftijd opneemt", "Voor fiscale facilitering moet het tegoed geblokkeerd zijn en aan voorwaarden voldoen."]], "1g.10"],
["Sinds wanneer kan een dga geen nieuw pensioen meer opbouwen in eigen beheer?", [["Sinds 1 april 2017", "Met de Wet uitfasering pensioen in eigen beheer is verdere opbouw per 1 april 2017 beëindigd."], ["Sinds 1 januari 2015", "Op die datum is de fiscale pensioenopbouw beperkt, maar pensioen in eigen beheer bestond nog."], ["Sinds 1 januari 2020", "Op die datum was de opbouw al jaren beëindigd."], ["Sinds 1 juli 2023", "Dat is de ingangsdatum van de Wtp, niet de datum van de uitfasering van pensioen in eigen beheer."]], "1j.3"],
["Welke keuzemogelijkheden had een dga bij de uitfasering van pensioen in eigen beheer?", [["Premievrij laten staan, afkopen met fiscale korting of omzetten in een oudedagsverplichting", "Afkopen met korting was alleen tijdelijk mogelijk; premievrij laten staan en de oudedagsverplichting bleven als opties over."], ["Het pensioen overdragen aan de SVB als aanvulling op de AOW, of het als dividend uitkeren uit de bv", "Pensioen in eigen beheer kan niet naar de SVB worden overgedragen."], ["Doorgaan met opbouw in eigen beheer tot de pensioendatum", "Verdere opbouw is juist beëindigd."], ["Het pensioen omzetten in een nettopensioen in eigen beheer", "Ook een nettopensioen kan niet in eigen beheer worden opgebouwd."]], "1j.3"],
["Wat is een oudedagsverplichting (ODV)?", [["Een verplichting van de bv om de dga vanaf een bepaalde leeftijd periodiek uit te keren, ontstaan uit pensioen in eigen beheer", "Bij de ODV vervalt het partnerpensioen; de waarde blijft in de bv."], ["Een verplichte lijfrente die elke dga bij een verzekeraar moet afsluiten over het loon boven de aftoppingsgrens", "De ODV is een verplichting van de eigen bv, geen verzekering."], ["De wettelijke verplichting van iedere werkgever met personeel om werknemers vanaf de AOW-leeftijd een aanvullend pensioen te bieden", "Een algemene werkgeversverplichting tot pensioen bestaat niet."], ["Een AOW-aanvulling voor ondernemers", "De ODV staat los van de AOW."]], "1j.3"],
["Gerrit (62) is dga van een transportbedrijf en heeft in zijn bv pensioen in eigen beheer opgebouwd. Hij is gehuwd met Marjan, die recht heeft op een partnerpensioen uit die regeling. Gerrit wil zijn pensioen in eigen beheer alsnog omzetten in een oudedagsverplichting. Marjan weet nog van niets. Wat is voor de omzetting nodig?", [["Schriftelijke toestemming van Marjan, omdat zij haar aanspraak op partnerpensioen verliest", "Bij omzetting in een ODV vervalt het partnerpensioen; daarom moet de partner schriftelijk instemmen."], ["Voorafgaande toestemming van de Belastingdienst, aan te vragen via een fiscaal vooroverleg", "Een vooroverleg met de Belastingdienst is voor deze omzetting niet vereist."], ["Een besluit van de AFM, omdat het om een wijziging van een pensioenproduct gaat", "De AFM heeft geen rol bij de omzetting van pensioen in eigen beheer."], ["Niets, Gerrit beslist als dga zelfstandig zonder dat Marjan erbij betrokken hoeft te worden", "Omdat Marjan haar partnerpensioen verliest, is haar instemming juist vereist."]], "1j.16"],
["Waarom kon een dga met een aanmerkelijk belang vroeger pensioen in eigen beheer opbouwen, terwijl dat voor gewone werknemers niet mocht?", [["Omdat de onderbrengingsplicht van de Pensioenwet niet geldt voor de directeur-grootaandeelhouder", "De Pensioenwet beschermt werknemers; voor de dga gold de verplichting om extern onder te brengen niet."], ["Omdat de dga geen AOW ontvangt", "De dga heeft gewoon recht op AOW; dat was niet de reden."], ["Omdat de AFM daarvoor een vergunning afgaf", "Voor pensioen in eigen beheer was geen AFM-vergunning nodig."], ["Omdat de bv daarvoor premie afdroeg aan een bedrijfstakpensioenfonds, dat het pensioen weer aan de bv uitleende", "Bij pensioen in eigen beheer bleef het pensioen juist binnen de eigen bv."]], "1j.19"],
["Hoe kan een dga na de uitfasering van pensioen in eigen beheer nog fiscaal gefaciliteerd voor zijn oude dag sparen?", [["Via een pensioenregeling bij een externe uitvoerder, zoals een verzekeraar, of via lijfrente binnen de jaarruimte", "Opbouw in eigen beheer is niet meer mogelijk, maar externe onderbrenging en lijfrente wel."], ["Door in een tweede, nieuw opgerichte eigen bv opnieuw pensioen in eigen beheer op te bouwen, los van de werkmaatschappij", "Ook in een andere eigen bv kan geen pensioen in eigen beheer meer worden opgebouwd."], ["Door de AOW-leeftijd fiscaal te laten vervroegen", "De AOW-leeftijd is wettelijk bepaald en kan niet fiscaal worden vervroegd."], ["Door privévermogen fiscaal vrijgesteld in box 2 te parkeren", "Een dergelijke vrijstelling bestaat niet."]], "1j.20"],
["Welke rol speelt het loon van de dga bij een externe pensioenregeling?", [["De pensioengrondslag is gebaseerd op het werkelijk genoten loon uit de bv, binnen de fiscale grenzen", "Het pensioen moet passen bij het loon dat de dga werkelijk ontvangt; dividend telt niet mee."], ["Dividenduitkeringen tellen volledig mee als pensioengevend loon, omdat de dga ook aandeelhouder van de bv is", "Dividend is geen loon en is niet pensioengevend."], ["De dga mag een willekeurige pensioengrondslag kiezen", "De grondslag moet aansluiten bij het werkelijke loon en de fiscale regels."], ["Het loon speelt geen rol omdat de dga geen werknemer is", "Fiscaal is de dga werknemer van zijn bv en speelt zijn loon wel een rol."]], "1j.20"],
["Een dga heeft zijn pensioen in eigen beheer premievrij laten staan. Wat betekent dat?", [["De opgebouwde aanspraken blijven in de bv staan, maar er komt geen nieuwe opbouw meer bij", "De bv blijft de verplichting houden het opgebouwde pensioen uit te keren."], ["Het pensioen is daarmee automatisch overgedragen aan een verzekeraar, die de verdere uitvoering overneemt", "Premievrij laten staan betekent juist dat het in de bv blijft."], ["Het pensioen is afgekocht en belast", "Afkoop is een andere keuze dan premievrij laten staan."], ["De bv mag de pensioenverplichting vrij laten vallen", "De bv blijft de verplichting houden tegenover de dga en zijn partner."]], "1j.6"],
["Welke beperking geldt voor een premiepensioeninstelling (PPI)?", [["Een PPI mag alleen premieovereenkomsten uitvoeren en geen biometrische risico's zoals overlijden zelf dragen", "Overlijdens- en arbeidsongeschiktheidsrisico's moet een PPI herverzekeren of bij een verzekeraar onderbrengen."], ["Een PPI mag alleen uitkeringsovereenkomsten uitvoeren en moet daarvoor een solvabiliteitsbuffer aanhouden", "Een PPI is juist bedoeld voor premieovereenkomsten."], ["Een PPI mag alleen pensioenregelingen uitvoeren voor overheidswerkgevers en instellingen in de semipublieke sector", "Een PPI kan door werkgevers in alle sectoren worden gebruikt."], ["Een PPI mag geen beleggingen doen met de premies", "Het beleggen van premies is juist de kern van een PPI."]], "1h.23"],
["Wat is een bedrijfstakpensioenfonds?", [["Een pensioenfonds voor een hele bedrijfstak, waarin de minister deelneming verplicht kan stellen", "Na een verplichtstelling moeten werkgevers in die bedrijfstak aansluiten, tenzij vrijstelling geldt."], ["Een pensioenfonds voor één onderneming of concern", "Dat is een ondernemingspensioenfonds."], ["Een fonds voor beoefenaren van een vrij beroep, zoals medisch specialisten, notarissen en apothekers", "Dat is een beroepspensioenfonds."], ["Een fonds dat door een verzekeraar wordt uitgevoerd onder een verzekeringsvergunning van DNB", "Een bedrijfstakpensioenfonds is een zelfstandige stichting, geen verzekeraar."]], "1g.8"],
["Wat is een kenmerk van een algemeen pensioenfonds (APF)?", [["Het kan regelingen van meerdere werkgevers uitvoeren in financieel gescheiden collectiviteitkringen", "Elke kring heeft een eigen vermogen, zodat tekorten niet worden doorgeschoven naar andere kringen."], ["Het voert uitsluitend de AOW uit", "De AOW wordt uitgevoerd door de SVB."], ["Het is een verzekeraar die ook bankdiensten aanbiedt", "Een APF is een pensioenfonds, geen verzekeraar of bank."], ["Het mag alleen werkgevers met minder dan 50 werknemers bedienen die niet onder een verplichtstelling vallen", "Voor een APF geldt geen grens op basis van het aantal werknemers."]], "1g.11"],
["Welke toezichthouders zijn betrokken bij pensioenuitvoerders?", [["DNB houdt prudentieel toezicht en de AFM gedragstoezicht, waaronder op pensioencommunicatie", "DNB bewaakt de financiële soliditeit, de AFM onder meer de informatieverstrekking aan deelnemers."], ["Alleen de AFM, omdat pensioen een financieel product is en zij ook de financiële soliditeit bewaakt", "De financiële soliditeit valt onder DNB."], ["Alleen DNB, omdat pensioenfondsen geen klanten hebben", "Ook de AFM houdt toezicht, bijvoorbeeld op de pensioencommunicatie."], ["De SVB en het UWV samen", "SVB en UWV zijn uitvoeringsorganisaties, geen toezichthouders op pensioenuitvoerders."]], "1a.4"],
["Stefan is eigenaar van een architectenbureau met 25 medewerkers. Zijn bedrijf valt niet onder een verplichtgesteld bedrijfstakpensioenfonds. Hij wil een premieregeling invoeren met een partnerpensioen op risicobasis. Hij vraagt zijn adviseur welke soorten uitvoerders hij daarvoor kan benaderen. Wat is juist?", [["Een pensioenverzekeraar, een PPI met herverzekering van het overlijdensrisico of een daarvoor openstaand apf", "Al deze uitvoerders kunnen een premieregeling uitvoeren; een PPI mag het overlijdensrisico niet zelf dragen en laat het herverzekeren."], ["Alleen een PPI, omdat verzekeraars geen premieregelingen uitvoeren en fondsen alleen verplichte regelingen", "Verzekeraars voeren wel premieregelingen uit en ook een apf staat open voor vrijwillige aansluiting."], ["Alleen een bank met een lijfrentevergunning, die het overlijdensrisico herverzekert", "Een bank is geen pensioenuitvoerder in de zin van de Pensioenwet."], ["Zijn eigen onderneming, door de regeling in eigen beheer uit te voeren", "Voor werknemers geldt de onderbrengingsplicht; eigen beheer is niet toegestaan."]], "1i.11"],
["Welke informatie moet een adviseur in elk geval verzamelen voor een goed pensioenadvies aan een particulier?", [["Financiële positie, kennis en ervaring, doelen en risicobereidheid, inclusief bestaande AOW- en pensioenaanspraken", "Pas met dat volledige klantbeeld kan het advies passend zijn."], ["Alleen het bruto jaarinkomen en de gewenste pensioenleeftijd, omdat de rest uit het landelijke online pensioenoverzicht blijkt", "Het inkomen is één onderdeel van het klantprofiel, niet het geheel."], ["Alleen de gewenste pensioenleeftijd", "De pensioenleeftijd is een wens, geen volledig klantprofiel."], ["Uitsluitend het UPO van de laatste werkgever en het bruto jaarinkomen, omdat de AOW voor iedereen gelijk is", "Eén UPO geeft geen volledig beeld; ook AOW, andere pensioenen en de persoonlijke situatie tellen mee."]], "1h.14"],
["Wat houdt de zorgplicht van een pensioenuitvoerder bij een premieregeling met beleggingskeuzes in?", [["De uitvoerder moet de deelnemer bij keuzes begeleiden en rekening houden met zijn risicoprofiel", "De deelnemer draagt beleggingsrisico; daarom moet de uitvoerder helpen bij passende keuzes."], ["De uitvoerder garandeert een minimale uitkering op de pensioendatum, ten minste gelijk aan de som van de ingelegde premies", "Een zorgplicht is geen garantie op een bepaalde uitkering."], ["De uitvoerder hoeft niets te doen, de deelnemer is zelf verantwoordelijk", "De wet legt juist een zorgplicht bij de uitvoerder."], ["De uitvoerder moet het pensioenvermogen van de deelnemer bij een bank stallen, zodat er geen beleggingsrisico meer is", "Dat is geen invulling van de zorgplicht."]], "1f.1"],
["Thomas (66) heeft bij zijn werkgever een premieregeling bij een verzekeraar en gaat over een paar maanden met pensioen. Op zijn pensioendatum staat er een flink kapitaal klaar. Een vriend vertelde hem dat andere verzekeraars soms een hogere uitkering bieden voor hetzelfde kapitaal. Thomas vraagt of hij zijn uitkering elders mag aankopen. Wat is juist?", [["Ja, hij heeft in beginsel shoprecht en kan met het kapitaal elders een uitkering aankopen", "Bij een premieovereenkomst mag de deelnemer in beginsel met het kapitaal bij een andere uitvoerder een uitkering kopen."], ["Nee, de uitkering moet altijd bij de eigen uitvoerder worden aangekocht tegen het tarief uit het reglement", "Het shoprecht geeft juist de mogelijkheid om elders aan te kopen."], ["Ja, maar alleen bij een bank, als bancaire lijfrente die hij vrij kan opnemen", "Het kapitaal moet worden omgezet in een pensioenuitkering en kan niet vrij worden opgenomen."], ["Nee, shoppen kan alleen bij een uitkeringsovereenkomst en niet bij een premieregeling", "Het shoprecht hoort juist bij de premieovereenkomst."]], "1g.13"],
["Een werkgever vraagt een adviseur een nieuwe collectieve pensioenregeling te selecteren. Wat hoort bij zorgvuldig advies?", [["Wensen en situatie van werkgever en werknemers inventariseren, uitvoerders en kosten vergelijken en de keuze vastleggen", "Zo kan de werkgever een onderbouwde keuze maken die past bij zijn doelen en budget."], ["Direct de uitvoerder met de laagste premie kiezen, omdat dekking en service bij alle uitvoerders wettelijk gelijk zijn geregeld", "Premie alleen is onvoldoende; ook dekking, kosten en kwaliteit van de uitvoering tellen mee."], ["Alleen de werknemers laten stemmen over de uitvoerder en de uitslag van de stemming vastleggen in de cao", "De werkgever kiest; draagvlak bij werknemers en een eventueel instemmingsrecht van de OR zijn wel relevant."], ["De keuze overlaten aan de toezichthouder", "De toezichthouder adviseert werkgevers niet over de keuze van een uitvoerder."]], "1c.12"],
["Harm (67) gaat binnenkort met pensioen en is gehuwd met Riet, die een kleine AOW-aanvulling heeft. Zijn pensioenfonds biedt hem de keuze uit een hoog-laagconstructie, uitruil tussen ouderdoms- en partnerpensioen en een bedrag ineens. Harm ontvangt ook zorgtoeslag. Hij vraagt zijn adviseur welke keuze het beste is. Wat is de juiste aanpak?", [["De keuzes in samenhang bekijken met de financiële situatie, Riet, toeslagen en fiscaliteit, en de gevolgen uitleggen", "Pensioenkeuzes beïnvloeden elkaar en hebben gevolgen voor partner, belasting en toeslagen; goed advies weegt dat samen af."], ["Altijd het maximale bedrag ineens adviseren, omdat Harm dan zelf over zijn pensioenvermogen beschikt", "Een bedrag ineens verlaagt het levenslange pensioen en kan toeslagen raken; het is niet altijd verstandig."], ["Alleen de keuze met het hoogste bruto bedrag adviseren, omdat die netto ook altijd het meest oplevert", "Een hoger bruto bedrag levert door belasting en toeslagen niet altijd netto meer op."], ["De keuzes aan de pensioenuitvoerder overlaten, omdat die de regeling het beste kent", "De uitvoerder begeleidt bij keuzes maar adviseert Harm niet over zijn totale situatie."]], "1g.5"],
["Wat is Pensioen 1-2-3?", [["Gelaagde pensioeninformatie: laag 1 de kern, laag 2 verdieping en laag 3 alle details en documenten", "Zo kan de deelnemer zelf bepalen hoe diep hij in de informatie duikt."], ["Een stappenplan voor het aanvragen van AOW", "De AOW-aanvraag loopt via de SVB en heeft niets met Pensioen 1-2-3 te maken."], ["Drie verplichte keuzes die een deelnemer jaarlijks moet maken: pensioenleeftijd, beleggingsprofiel en partnerdekking", "Pensioen 1-2-3 is een informatieopzet, geen keuzemoment."], ["Een classificatie van pensioenfondsen naar risico", "Het is geen risicoclassificatie van uitvoerders."]], "1g.13"],
["Wat kan een deelnemer vinden in het landelijke online pensioenoverzicht dat hij met zijn DigiD kan inzien?", [["Een overzicht van de AOW en het via werkgevers opgebouwde pensioen bij de verschillende uitvoerders", "Door in te loggen met DigiD ziet de gebruiker zijn eerste- en tweedepijleraanspraken samen."], ["Een volledig overzicht van alle bankrekeningen en spaargelden", "Gewone banktegoeden staan niet op het landelijke online pensioenoverzicht."], ["Een gegarandeerde berekening van het netto besteedbaar inkomen na pensionering, inclusief toeslagen en belasting", "Het overzicht geeft bruto aanspraken en indicaties, geen garantie op netto inkomen."], ["Een vergelijking van pensioenuitvoerders met rangschikking", "De site vergelijkt geen uitvoerders."]], "1h.14"],
["Een klant print zijn landelijke online pensioenoverzicht uit voor een pensioenadvies. Wat moet de adviseur daarnaast in het algemeen nog uitvragen?", [["Eigen derdepijlervoorzieningen, zoals lijfrentes en banksparen, en de situatie van de partner", "Die gegevens staan in de regel niet op het overzicht, maar zijn nodig voor een volledig advies."], ["Niets, het overzicht bevat alle relevante pensioeninformatie", "Derdepijlerproducten en de partnersituatie ontbreken doorgaans."], ["Alleen de AOW-gegevens, omdat die niet op het overzicht staan", "De AOW staat juist wel op het overzicht."], ["Alleen de pensioenen uit het buitenland, omdat de derde pijler en partnergegevens er al wel op staan", "Lijfrentes en partnergegevens staan juist niet op het overzicht; ook buitenlandse pensioenen ontbreken er in de regel."]], "1h.14"],
["Wat is een belangrijk doel van de Wet pensioencommunicatie?", [["Deelnemers beter laten begrijpen wat hun pensioen inhoudt, met informatie die aansluit bij hun behoefte", "Met gelaagde informatie en digitale mogelijkheden moet pensioen begrijpelijker worden."], ["Het verplicht maken van pensioenadvies voor iedere werknemer voordat hij een keuze in zijn pensioenregeling maakt", "De wet verplicht niet tot het inwinnen van advies."], ["Het afschaffen van het Uniform Pensioenoverzicht", "Het UPO bestaat nog steeds."], ["Het overdragen van alle pensioencommunicatie aan de AFM", "De uitvoerder blijft verantwoordelijk voor de communicatie; de AFM houdt toezicht."]], "1h.13"],
["Wat moet een verzekeringsdistributeur onder de IDD vóór het sluiten van een verzekering in ieder geval vaststellen?", [["De wensen en behoeften van de klant, zodat het aangeboden product daarbij past", "Deze verplichting geldt ook als er geen advies wordt gegeven."], ["Het nummer van de kredietregistratie van de klant", "Een toets in de kredietregistratie hoort bij krediet en niet bij de IDD-verplichting."], ["Het pensioenvermogen van de klant bij de werkgever, zoals vermeld op het meest recente UPO", "Dat kan relevant zijn, maar is niet de algemene IDD-verplichting."], ["Of de klant al eerder een verzekering heeft opgezegd", "De IDD vraagt de wensen en behoeften, niet de opzeggingsgeschiedenis."]], "2c.1"],
["Wat is een voordeel van assetpooling binnen een algemeen pensioenfonds (apf)?", [["Kringen kunnen gezamenlijk beleggen, wat schaalvoordeel en lagere kosten kan geven", "Bij assetpooling wordt het vermogen van kringen gezamenlijk belegd, terwijl elke kring financieel afgescheiden blijft."], ["Tekorten in de ene kring worden automatisch aangevuld uit het vermogen van een andere kring", "Collectiviteitskringen zijn financieel gescheiden; een tekort wordt niet uit een andere kring betaald."], ["Het apf hoeft door gezamenlijk beleggen geen vergunning van DNB te hebben", "Een apf heeft altijd een vergunning van DNB nodig."], ["Het beleggingsrisico verdwijnt volledig voor de deelnemers", "Gezamenlijk beleggen verandert niets aan het bestaan van beleggingsrisico."]], "1f.4"],
["Bij een werkgever is de pensioenregeling inhoudelijk volledig geregeld in de cao die op hem van toepassing is. Heeft de ondernemingsraad instemmingsrecht bij de invoering van die regeling?", [["Nee, voor zover de cao de regeling al inhoudelijk regelt, vervalt het instemmingsrecht", "Het instemmingsrecht van de OR geldt niet voor zover een onderwerp al inhoudelijk in een cao is geregeld."], ["Ja, de OR heeft altijd instemmingsrecht bij pensioen, ook als de cao alles regelt", "Het instemmingsrecht vervalt juist voor zover de cao de zaak al inhoudelijk regelt."], ["Ja, en de OR mag dan ten nadele van de werknemers van de cao afwijken", "De OR kan een cao niet opzijzetten."], ["Nee, omdat de OR bij pensioen nooit enige bevoegdheid heeft", "Zonder cao-regeling heeft de OR wel instemmingsrecht bij pensioen."]], "1g.9"],
["Wat moet een instelling onder de Wwft doen met een ongebruikelijke transactie?", [["Onverwijld melden bij de FIU-Nederland", "De melding moet onverwijld worden gedaan zodra het ongebruikelijke karakter bekend is."], ["Melden bij de AFM binnen dertig dagen", "Ongebruikelijke transacties worden gemeld bij de FIU-Nederland, niet bij de AFM."], ["De klant direct vertellen dat er een melding wordt gedaan", "Het is juist verboden de klant over de melding te informeren."], ["Alleen melden als het bedrag boven een vaste grens ligt", "Ook subjectieve indicatoren kunnen tot een meldplicht leiden, ongeacht het bedrag."]], "4a.1"],
["Hoe zijn de fiscale regels voor werkgeverspensioen en voor lijfrente in hoofdzaak over de Wet op de loonbelasting (Wet LB) en de Wet inkomstenbelasting (Wet IB) verdeeld?", [["De fiscale regels voor werkgeverspensioen staan in de Wet LB, die voor lijfrente in de Wet IB", "De pensioenregeling valt fiscaal in de loonsfeer; de lijfrente is een voorziening in de inkomstenbelasting."], ["Zowel werkgeverspensioen als lijfrente is volledig in de Wet IB geregeld", "Het fiscale kader voor werkgeverspensioen staat in de Wet LB."], ["Werkgeverspensioen valt onder de Wet IB en lijfrente onder de Wet LB", "Het is precies andersom."], ["Beide vallen alleen onder de Pensioenwet; de belastingwetten spelen geen rol", "De Pensioenwet regelt civiele en toezichtzaken; de fiscale regels staan in de belastingwetten."]], "1g.10"],
["Een klant die een politiek prominente functie bekleedt, wil een omvangrijke lijfrente-inleg doen. Wat vraagt de Wwft van de instelling?", [["Verscherpt cliëntenonderzoek, onder meer naar de herkomst van het vermogen", "Bij een politiek prominent persoon geldt een hoger risico op bijvoorbeeld corruptie."], ["Niets bijzonders, het gewone cliëntenonderzoek volstaat altijd", "Bij een PEP is verscherpt cliëntenonderzoek verplicht."], ["De zakelijke relatie direct weigeren", "Een PEP mag klant zijn, maar onder verscherpte maatregelen."], ["Een melding bij de FIU-Nederland, ongeacht de omvang of aard van de transactie", "Een PEP-status is op zich geen reden voor een melding."]], "4a.1"],
["Tot welke pijler behoort een verplichte beroepspensioenregeling, bijvoorbeeld voor huisartsen of medisch specialisten?", [["De tweede pijler", "Collectieve regelingen via de werkgever of de beroepsgroep, ook verplichte beroepspensioenregelingen, vormen de tweede pijler."], ["De derde pijler", "De derde pijler bestaat uit individuele, vrijwillige voorzieningen; een verplichte beroepsregeling is collectief geregeld."], ["De eerste pijler", "De eerste pijler is de AOW, een volksverzekering van de overheid voor alle ingezetenen, geen beroepsregeling."], ["Geen van de pijlers, omdat het om zelfstandigen gaat", "Ook zelfstandige beroepsbeoefenaren kunnen via een verplichte beroepspensioenregeling in de tweede pijler opbouwen."]], "1g.8"],
["Hoe wordt het werkgeverspensioen in de tweede pijler in hoofdzaak gefinancierd?", [["Via kapitaaldekking: premies worden belegd en daaruit wordt het pensioen betaald", "In de tweede pijler wordt vermogen opgebouwd dat wordt belegd; de uitkeringen worden betaald uit dat gespaarde vermogen en het rendement daarop."], ["Via een omslagstelsel waarbij de werkenden van nu de lopende pensioenen van de gepensioneerden betalen", "Een omslagstelsel is kenmerkend voor de AOW in de eerste pijler, niet voor het werkgeverspensioen."], ["Volledig uit de algemene middelen van de rijksbegroting", "De overheid financiert het werkgeverspensioen niet; het wordt betaald uit premies van werkgever en werknemer en uit beleggingsrendement."], ["Uitsluitend uit de premies van de werkgever, zonder belegging", "Premies worden juist belegd, en ook de werknemer betaalt vaak mee via een eigen bijdrage."]], "1f.3"],
["Bij pensioenplanning wordt vaak gerekend met een streefinkomen. Welk uitgangspunt wordt daarbij in de praktijk veel gebruikt als vuistregel?", [["Ongeveer 70% van het laatstverdiende of gemiddelde brutoloon, inclusief AOW", "Een streefinkomen van circa 70% van het brutoloon, AOW meegerekend, is een veelgebruikte vuistregel; de werkelijke behoefte verschilt per klant."], ["Precies 100% van het laatste nettoloon, wettelijk gegarandeerd", "Er bestaat geen wettelijke garantie op een bepaald pensioeninkomen; 100% netto is geen gangbare norm."], ["Het netto minimumloon, omdat de AOW daarop is gebaseerd", "De AOW is gekoppeld aan het minimumloon, maar het streefinkomen van een werknemer ligt in de regel hoger."], ["50% van het brutoloon, exclusief AOW, als wettelijke minimumnorm", "De wet schrijft geen minimale hoogte van het aanvullend pensioen voor; dit is geen wettelijke norm."]], "1h.14"],
["Wat is een belangrijk risico van de derde pijler in vergelijking met de tweede pijler?", [["Opbouw hangt af van eigen discipline; er is geen werkgever die meebetaalt of risico's collectief deelt", "Individuele voorzieningen worden alleen opgebouwd als de klant zelf inlegt, zonder werkgeversbijdrage of collectieve risicodeling."], ["Derdepijlerproducten zijn nooit fiscaal gefaciliteerd", "Lijfrente en banksparen zijn binnen de jaarruimte en reserveringsruimte juist wel fiscaal gefaciliteerd."], ["De uitkering uit de derde pijler wordt altijd gekort op de AOW, omdat de AOW rekening houdt met ander inkomen", "De AOW kent geen inkomens- of vermogenstoets, dus derdepijlerinkomen leidt niet tot korting op de AOW."], ["Een derdepijlervoorziening vervalt bij wisseling van werkgever", "Een individuele voorziening staat los van de werkgever en blijft bij een baanwissel gewoon bestaan."]], "1c.5"],
["Linda (40) werkt als zzp'er en heeft nooit bij een werkgever pensioen opgebouwd. Welke pijlers dragen naar verwachting bij aan haar oudedagsinkomen als zij niets extra regelt?", [["Alleen de eerste pijler, de AOW", "Zonder werkgeverspensioen en eigen voorzieningen heeft Linda alleen recht op AOW, mits zij in Nederland woont of werkt."], ["De eerste en de tweede pijler", "Een zzp'er bouwt zonder dienstverband of verplichte beroepsregeling geen tweedepijlerpensioen op."], ["De eerste en de derde pijler", "De derde pijler ontstaat alleen als Linda zelf een voorziening treft, zoals een lijfrente."], ["Geen enkele pijler, omdat zij ondernemer is", "Ook ondernemers zijn verzekerd voor de AOW zolang zij in Nederland wonen of hier werken."]], "1h.14"],
["Kan iemand de ingangsdatum van zijn AOW naar eigen keuze vervroegen of uitstellen?", [["Nee, de AOW gaat in op de wettelijke AOW-leeftijd en kan niet worden vervroegd of uitgesteld", "De AOW-leeftijd is wettelijk vastgelegd; eerder stoppen met werken moet met eigen of pensioenmiddelen worden overbrugd."], ["Ja, vervroegen kan tot maximaal vijf jaar vóór de AOW-leeftijd, met een levenslang lagere uitkering", "Een flexibele AOW met vervroeging bestaat niet; dat kan wel bij het ouderdomspensioen uit de tweede pijler."], ["Ja, uitstellen kan en levert dan een hogere AOW op", "Een uitstelmogelijkheid met verhoging bestaat voor de AOW niet; dat is een keuze bij het aanvullend pensioen."], ["Alleen vervroegen, en alleen bij een zwaar beroep", "Ook voor zware beroepen bestaat geen vervroegde AOW; daarvoor bestaan andere regelingen via de werkgever."]], "1h.3"],
["Een werkgever heeft een uitkeringsovereenkomst bij een pensioenverzekeraar, waarbij de inkoop van de jaarlijkse opbouw per deelnemer afhangt van de leeftijd. Het personeelsbestand vergrijst de komende jaren. Wat is het te verwachten effect op de pensioenlasten?", [["De lasten stijgen, omdat inkoop van dezelfde opbouw duurder is naarmate de deelnemer ouder is", "Voor een oudere deelnemer is er minder tijd voor rendement, dus kost dezelfde opbouw meer."], ["De lasten dalen, omdat oudere werknemers minder lang premie betalen", "De inkoop per jaar wordt juist duurder naarmate de deelnemer ouder is."], ["De lasten blijven gelijk, omdat de leeftijd bij een uitkeringsovereenkomst geen rol speelt", "Bij leeftijdsafhankelijke inkoop speelt leeftijd juist een grote rol."], ["Er is geen effect, omdat alleen de dekkingsgraad van de verzekeraar de lasten bepaalt", "Een verzekeraar heeft geen dekkingsgraad zoals een fonds; de lasten volgen uit de inkooptarieven."]], "1h.5"],
["Een werkgever wil werknemers met een tijdelijk contract uitsluiten van de pensioenregeling die geldt voor werknemers met een vast contract. Is dat toegestaan?", [["Nee, onderscheid tussen tijdelijke en vaste contracten is verboden, tenzij objectief gerechtvaardigd", "Het verbod op onderscheid naar de duur van de arbeidsovereenkomst geldt ook voor pensioen."], ["Ja, tijdelijke werknemers mogen altijd van de pensioenregeling worden uitgesloten", "Uitsluiting alleen vanwege een tijdelijk contract is in strijd met het verbod op onderscheid."], ["Ja, zolang het tijdelijke contract korter duurt dan twee jaar", "De wet kent zo'n vrijstelling voor korte contracten niet."], ["Alleen als de werkgever onder een verplicht bedrijfstakpensioenfonds valt", "Een verplichtstelling maakt uitsluiting van tijdelijke werknemers niet mogelijk."]], "1h.8"],
["Waarom is het belastingtarief in de eerste schijf voor iemand die de AOW-leeftijd heeft bereikt lager dan voor iemand jonger?", [["Omdat een AOW-gerechtigde geen premie AOW meer betaalt", "De premie volksverzekeringen voor de AOW maakt deel uit van het gecombineerde tarief in de eerste schijf; na de AOW-leeftijd vervalt die premie."], ["Omdat pensioeninkomen een eigen, lager tarief in box 2 kent", "Pensioeninkomen valt in box 1, niet in box 2; box 2 betreft inkomen uit aanmerkelijk belang."], ["Omdat AOW'ers geen premie Anw meer verschuldigd zijn", "Ook AOW-gerechtigden betalen nog premie Anw en Wlz; het verschil komt door het vervallen van de AOW-premie."], ["Omdat de algemene heffingskorting na de AOW-leeftijd verdubbelt", "Heffingskortingen zijn juist lager voor AOW'ers; het lagere tarief komt door het wegvallen van de AOW-premie."]], "1g.10"],
["Gerard is 66 jaar en bereikt over een paar maanden de AOW-leeftijd. Hij is gehuwd met Anja (59), die al jaren geen eigen inkomen heeft. Een kennis die in 2012 met pensioen ging, kreeg destijds een toeslag voor zijn jongere vrouw. Gerard wil die toeslag ook aanvragen. Kan hij een partnertoeslag voor Anja krijgen?", [["Nee, voor nieuwe gevallen bestaat de partnertoeslag niet meer; hij krijgt AOW voor samenwonenden", "De partnertoeslag is voor nieuwe gevallen afgeschaft; Gerard ontvangt de AOW voor gehuwden en samenwonenden."], ["Ja, hij krijgt een aanvullende toeslag op zijn AOW totdat Anja zelf de AOW-leeftijd bereikt", "Die regeling geldt niet meer voor wie nu de AOW-leeftijd bereikt."], ["Ja, omdat Anja geen eigen inkomen heeft en de partnertoeslag dan inkomensafhankelijk wordt toegekend", "Ook zonder inkomen van de partner bestaat voor nieuwe gevallen geen partnertoeslag."], ["Nee, maar Gerard krijgt in plaats daarvan de AOW voor alleenstaanden zolang Anja jonger is", "Gehuwden krijgen de AOW voor samenwonenden, ongeacht de leeftijd van de partner."]], "1h.3"],
["Gelden ongehuwd samenwonende AOW-gerechtigden voor de AOW als alleenstaand?", [["Nee, bij een gezamenlijke huishouding gelden zij als samenwonend, ook zonder huwelijk", "De AOW kijkt naar de feitelijke leefsituatie: wie met een ander een gezamenlijke huishouding voert, krijgt de AOW voor samenwonenden."], ["Ja, alleen gehuwden en geregistreerde partners gelden als samenwonend", "De AOW gaat niet alleen uit van de burgerlijke staat; ook ongehuwd samenwonenden kunnen als samenwonend gelden."], ["Ja, zolang zij geen samenlevingscontract hebben", "Een samenlevingscontract is niet bepalend; het gaat om het feitelijk voeren van een gezamenlijke huishouding."], ["Nee, maar alleen als zij langer dan tien jaar samenwonen", "Een minimale samenwoonduur is geen voorwaarde; het voeren van een gezamenlijke huishouding is bepalend."]], "1h.3"],
["Rob is 70 jaar, alleenstaand en ontvangt AOW. Zijn broer Frans is ernstig ziek geworden en kan niet meer alleen wonen. Frans trekt bij Rob in, zodat Rob hem kan verzorgen. Rob is bang dat hij nu als samenwonend wordt gezien en minder AOW krijgt. Wat kan voor de hoogte van Robs AOW gelden?", [["Onder voorwaarden geldt een mantelzorguitzondering, zodat Rob de AOW voor alleenstaanden kan houden", "Bij zorg binnen één huis kan onder voorwaarden een uitzondering gelden, zodat beiden als alleenstaand blijven gelden."], ["Rob krijgt automatisch een extra toeslag op zijn AOW voor de mantelzorg die hij verleent", "De AOW kent geen mantelzorgtoeslag."], ["Robs AOW stopt volledig zolang zijn broer bij hem woont", "Er is geen grond waarop de AOW door inwoning stopt."], ["Rob moet zijn AOW laten omzetten in bijstand, omdat er nu een gezamenlijke huishouding is", "De AOW blijft bestaan; de vraag is alleen of hij als alleenstaande of samenwonende geldt."]], "1h.3"],
["Nina (35) is software-engineer en heeft altijd in Nederland gewoond en gewerkt. Zij krijgt een baan in Toronto aangeboden en emigreert volgende maand naar Canada. Daar gaat zij in loondienst werken bij een Canadese werkgever. Nina vraagt wat er gebeurt met haar AOW-opbouw. Wat is juist?", [["Haar opbouw stopt in beginsel; onder voorwaarden kan zij zich vrijwillig verzekeren bij de SVB", "AOW bouw je op door wonen of werken in Nederland; wie vertrekt, kan zich onder voorwaarden vrijwillig verzekeren."], ["Haar AOW-opbouw loopt gewoon door zolang zij de Nederlandse nationaliteit heeft", "Opbouw hangt af van wonen of werken in Nederland, niet van nationaliteit."], ["Zij verliest ook de AOW die zij tot haar vertrek heeft opgebouwd", "De al opgebouwde AOW blijft behouden en wordt later ook in het buitenland uitbetaald."], ["Haar AOW-opbouw wordt automatisch voortgezet via haar Nederlandse pensioenfonds", "Een pensioenfonds voert de AOW niet uit; dat doet de SVB."]], "1h.14"],
["Wanneer is er in een pensioenregeling sprake van verboden leeftijdsdiscriminatie?", [["Bij onderscheid naar leeftijd zonder objectieve rechtvaardiging en zonder wettelijke uitzondering", "Onderscheid naar leeftijd is alleen toegestaan als het objectief gerechtvaardigd is of onder een wettelijke uitzondering valt."], ["Altijd wanneer de premie of opbouw met de leeftijd verschilt, ook binnen een wettelijke uitzondering daarop", "De wet kent juist uitzonderingen waarbinnen leeftijdsonderscheid in pensioen is toegestaan."], ["Alleen als werknemers boven de AOW-leeftijd van deelname worden uitgesloten", "Leeftijdsdiscriminatie kan ook bij andere leeftijden en regels spelen."], ["Nooit, omdat pensioenregelingen buiten de regels voor gelijke behandeling vallen", "De regels voor gelijke behandeling gelden ook voor pensioen."]], "1h.12"],
["Femke is 63 jaar en werkt als docent in het voortgezet onderwijs. Zij wil stoppen met werken en haar ouderdomspensioen nu laten ingaan. Haar AOW-leeftijd ligt nog ruim drie jaar later. Ze vreest dat haar inkomen in die eerste jaren te laag is. Welke pensioenkeuze kan dat tijdelijke inkomensgat helpen opvangen?", [["Een hoog-laagconstructie, waarbij het pensioen eerst hoger en later lager uitkeert", "Met hoog-laag krijgt zij tot haar AOW-leeftijd een hoger pensioen, wat het ontbreken van de AOW deels opvangt."], ["Haar AOW vervroegen, zodat die tegelijk met haar pensioen ingaat", "De AOW kan niet worden vervroegd."], ["Een Anw-hiaatverzekering afsluiten die tot haar AOW-leeftijd uitkeert", "Een Anw-hiaatverzekering keert uit bij overlijden, niet bij vervroegd pensioen."], ["Een Anw-uitkering aanvragen die het ontbrekende inkomen tot de AOW-leeftijd aanvult", "De Anw is een nabestaandenuitkering en geldt niet bij eerder stoppen met werken."]], "1g.5"],
["Wat gebeurt er met de AOW van iemand die na de AOW-leeftijd blijft doorwerken in loondienst?", [["De AOW wordt gewoon volledig uitbetaald, ongeacht het arbeidsinkomen", "De AOW kent geen inkomenstoets; doorwerken heeft geen invloed op de hoogte ervan, wel op de totale belastingdruk."], ["De AOW wordt gekort met het verdiende loon", "Een korting op arbeidsinkomen geldt bij de Anw, niet bij de AOW."], ["De AOW wordt opgeschort totdat de werknemer stopt", "De AOW gaat in op de AOW-leeftijd en wordt niet opgeschort door het voortzetten van werk."], ["De werknemer gaat weer AOW-premie betalen en bouwt extra AOW op", "Na de AOW-leeftijd is geen AOW-premie meer verschuldigd en vindt geen verdere opbouw plaats."]], "1h.3"],
["Een grafisch bedrijf stapt per 1 januari met zijn pensioenregeling over van verzekeraar A naar verzekeraar B. Medewerker Ellen (51) is sinds oktober van het jaar ervoor ziek. Na de wachttijd wordt zij arbeidsongeschikt verklaard, zodat haar recht op premievrijstelling pas ná de overstap ingaat. Haar werkgever vraagt welke verzekeraar daarvoor moet zorgen. Welke verzekeraar draagt in beginsel de premievrijstelling voor Ellen?", [["Verzekeraar A, omdat Ellen ziek werd toen de regeling daar liep (uitlooprisico)", "Volgens het convenant over uitloop draagt de uitvoerder bij wie de deelnemer verzekerd was bij de eerste ziektedag het uitlooprisico."], ["Verzekeraar B, omdat de arbeidsongeschiktheid pas na de overstap is vastgesteld", "Voor de dekking telt de eerste ziektedag, niet het moment van vaststelling."], ["Geen van beide; de werkgever moet de pensioenpremie voor Ellen zelf blijven betalen", "De afspraken over uitloop voorkomen juist dat Ellen tussen twee verzekeraars in valt."], ["Het UWV, dat bij een overstap van verzekeraar de premievrijstelling overneemt", "Het UWV neemt geen premievrijstelling over bij een wisseling van verzekeraar."]], "1h.21"],
["Wordt een Anw-nabestaandenuitkering gekort als de nabestaande daarnaast een partnerpensioen uit de tweede pijler ontvangt?", [["Nee, partnerpensioen telt niet mee bij de inkomenstoets van de Anw", "De Anw kijkt naar inkomen uit arbeid en naar uitkeringen die daarvoor in de plaats komen; een nabestaandenpensioen wordt niet gekort."], ["Ja, het partnerpensioen wordt volledig op de Anw in mindering gebracht", "Dat geldt niet: de Anw-inkomenstoets ziet op arbeidsinkomen en vervangende uitkeringen, niet op pensioen."], ["Ja, voor de helft van het bruto partnerpensioen", "Er bestaat geen gedeeltelijke korting met pensioeninkomen; pensioen blijft buiten de toets."], ["Alleen als het partnerpensioen hoger is dan het minimumloon", "Er geldt geen drempel voor pensioen; pensioeninkomen speelt bij de Anw-inkomenstoets geen rol."]], "1h.16"],
["Welk soort inkomen kan wel leiden tot verlaging van een Anw-nabestaandenuitkering?", [["Inkomen uit arbeid en uitkeringen die daarvoor in de plaats komen, zoals WW of ziektewet", "De Anw is een vangnet met een inkomenstoets op arbeidsinkomen en vervangende uitkeringen, waarbij een deel vrijgelaten wordt."], ["Een uitkering uit een overlijdensrisicoverzekering", "Een eenmalige uitkering uit een eigen verzekering telt niet als inkomen voor de Anw."], ["Vermogen in box 3, zoals spaargeld, beleggingen en een tweede woning boven het heffingvrije vermogen", "De Anw kent geen vermogenstoets; alleen bepaald inkomen wordt meegewogen."], ["Het ouderdomspensioen van de overleden partner", "Dat pensioen eindigt bij overlijden; het is geen inkomen van de nabestaande dat de Anw beïnvloedt."]], "1h.16"],
["Wie kan aanspraak maken op een Anw-wezenuitkering?", [["Een kind van wie beide ouders zijn overleden, tot een wettelijk bepaalde leeftijd", "De Anw-wezenuitkering is bedoeld voor volle wezen; leeft één ouder nog, dan is er geen wezenuitkering uit de Anw."], ["Ieder kind van wie één ouder is overleden", "Bij halfwezen ontvangt de overgebleven ouder eventueel een nabestaandenuitkering; er is geen wezenuitkering voor het kind zelf."], ["Alleen kinderen van een overleden werknemer met een pensioenregeling", "Dat beschrijft een wezenpensioen uit de tweede pijler, niet de Anw als volksverzekering."], ["Ook volwassen kinderen ongeacht hun leeftijd", "De wezenuitkering is aan een maximumleeftijd gebonden en niet levenslang."]], "1i.5"],
["Esra (42) is weduwe sinds haar man drie jaar geleden overleed. Zij heeft een zoon van 16 en ontvangt daarom een Anw-nabestaandenuitkering. Esra werkt parttime en is niet arbeidsongeschikt. Over twee jaar wordt haar zoon 18. Wat gebeurt er dan met haar Anw-uitkering als er geen andere grond voor de Anw is?", [["De Anw-nabestaandenuitkering eindigt", "Als de zorg voor een kind onder 18 de enige grond was, eindigt de uitkering wanneer het kind 18 wordt."], ["De uitkering loopt door tot haar AOW-leeftijd", "Zonder geldige toegangsgrond loopt de Anw niet door tot de AOW-leeftijd."], ["De uitkering wordt omgezet in een wezenuitkering voor haar zoon", "Een wezenuitkering is voor kinderen van wie beide ouders zijn overleden."], ["De uitkering halveert, maar blijft daarna levenslang bestaan", "De Anw kent geen levenslange halve uitkering."]], "1h.16"],
["Bram heeft een café en heeft per 1 maart Lisa (29) in dienst genomen als bedrijfsleider. Er loopt een pensioenregeling bij een verzekeraar met een partnerpensioen op risicobasis. Bram is vergeten Lisa aan te melden. In juni overlijdt Lisa bij een verkeersongeluk. Haar partner vraagt nu naar het partnerpensioen. Wat is het risico voor Bram?", [["Bram kan aansprakelijk zijn voor het partnerpensioen dat zonder zijn verzuim zou zijn uitgekeerd", "Een werkgever die een werknemer niet tijdig aanmeldt, loopt het risico zelf voor de gemiste dekking op te moeten komen."], ["Geen, de verzekeraar moet ook zonder aanmelding altijd het volledige partnerpensioen uitkeren", "Of er dekking is zonder aanmelding hangt af van de contractvoorwaarden; zekerheid is er niet."], ["Geen, omdat de Anw het ontbrekende partnerpensioen dan volledig voor de partner overneemt", "De Anw is een volksverzekering met eigen voorwaarden en vervangt geen gemist partnerpensioen."], ["De verzekeraar verhaalt het verzuim op de partner van Lisa", "De partner heeft het verzuim niet veroorzaakt; het risico ligt bij de werkgever."]], "1h.21"],
["Dennis (50) is getrouwd met Mieke (48). Zij hebben geen kinderen. Mieke is na een ernstige ziekte door het UWV voor 50% arbeidsongeschikt verklaard. Dennis vraagt zijn adviseur of Mieke een Anw-uitkering kan krijgen als hij overlijdt. Wat is juist?", [["Zij kan recht hebben, omdat ten minste 45% arbeidsongeschiktheid een toegangsgrond is", "Een nabestaande die ten minste 45% arbeidsongeschikt is, kan recht hebben; de inkomenstoets kan de uitkering wel verlagen."], ["Nee, zonder kind onder 18 bestaat nooit recht op een Anw-uitkering", "Arbeidsongeschiktheid van ten minste 45% is een aparte toegangsgrond."], ["Ja, zij krijgt dan altijd een volledige Anw-uitkering, zonder inkomenstoets", "Inkomen uit arbeid of een vervangende uitkering kan de Anw verlagen."], ["Alleen als zij volledig en duurzaam arbeidsongeschikt is verklaard in de WIA", "De grens ligt bij 45% arbeidsongeschiktheid, niet bij volledige en duurzame arbeidsongeschiktheid."]], "1h.16"],
["Welke rol heeft een overlijdensrisicoverzekering in de afdekking van nabestaandenrisico's naast pensioen en Anw?", [["Zij keert bij overlijden een kapitaal uit om inkomensverlies of woonlasten op te vangen", "Een overlijdensrisicoverzekering geeft een eenmalige uitkering en is een flexibele aanvulling op partnerpensioen en Anw."], ["Zij verhoogt de AOW van de nabestaande levenslang", "De AOW is een volksverzekering en wordt niet verhoogd door een particuliere verzekering."], ["Zij vervangt het partnerpensioen dat de werkgever op grond van de Pensioenwet verplicht moet aanbieden", "Werkgevers zijn niet verplicht partnerpensioen te bieden; een ORV staat los van de pensioenregeling."], ["Zij keert pas uit op de AOW-leeftijd van de nabestaande", "Een overlijdensrisicoverzekering keert uit bij overlijden binnen de looptijd, niet op een vaste leeftijd."]], "1i.8"],
["Mag een pensioenuitvoerder een medische keuring eisen voordat een werknemer kan deelnemen aan de pensioenregeling van zijn werkgever?", [["Nee, de Pensioenwet verbiedt een medische keuring als voorwaarde voor deelname", "Deelname mag niet afhangen van de gezondheid; zo wordt voorkomen dat werknemers met een slechte gezondheid buiten de regeling vallen."], ["Ja, voor het partnerpensioen op risicobasis is dat gebruikelijk", "Ook voor het risicodeel van de collectieve regeling mag geen medische selectie plaatsvinden."], ["Ja, als de werknemer ouder is dan 50 jaar", "Er bestaat geen leeftijdsgrens waarboven een medische keuring wel is toegestaan voor deelname."], ["Alleen bij een pensioenverzekeraar, niet bij een pensioenfonds", "Het verbod geldt voor alle pensioenuitvoerders die een pensioenovereenkomst uitvoeren."]], "1i.3"],
["Het metaalbedrijf van Bart Kok (58) heeft een middelloonregeling bij een verzekeraar. De pensioenlasten zijn de laatste jaren sterk gestegen. Bart wil de regeling eenzijdig versoberen naar een premieregeling. In de pensioenovereenkomst is een wijzigingsbeding opgenomen. Wanneer mag hij dat beding inroepen?", [["Alleen bij een zo zwaarwichtig belang dat het belang van de werknemers naar redelijkheid moet wijken", "Een eenzijdige wijziging via het wijzigingsbeding kan alleen bij zo'n zwaarwichtig belang van de werkgever."], ["Altijd, omdat de werkgever de premie betaalt en dus over de inhoud beslist", "Premiebetaling geeft de werkgever geen onbeperkt recht om eenzijdig te wijzigen."], ["Alleen als de werknemers na een schriftelijke aankondiging niet binnen een maand bezwaar maken", "Stilzwijgen van werknemers is geen wettelijke maatstaf voor een eenzijdige wijziging."], ["Nooit, een pensioenregeling is na invoering onwijzigbaar, ook met een wijzigingsbeding", "Met een wijzigingsbeding is wijziging wel mogelijk, maar alleen bij een zwaarwichtig belang."]], "1g.3"],
["Mag een deelnemer zijn pensioenaanspraak verpanden aan een bank als zekerheid voor een lening?", [["Nee, pensioenaanspraken kunnen in beginsel niet worden vervreemd, verpand of belast", "Het vervreemdingsverbod beschermt de pensioenbestemming, zodat het pensioen beschikbaar blijft voor de oude dag en nabestaanden."], ["Ja, als de bank een vergunning van DNB heeft en de verpanding bij de uitvoerder is gemeld", "Een vergunning van de bank verandert niets aan het wettelijke verbod op verpanding van pensioen."], ["Ja, mits de partner schriftelijk toestemming geeft", "Partnertoestemming is nodig bij bijvoorbeeld uitruil, maar maakt verpanding van pensioen niet mogelijk."], ["Alleen voor de financiering van een eigen woning", "Ook voor een eigen woning geldt het verbod; pensioen kan niet als onderpand dienen."]], "1j.5"],
["Wat houdt het afkoopverbod van de Pensioenwet in hoofdzaak in?", [["Afkoop is verboden, behalve in wettelijke uitzonderingen zoals een klein pensioen", "Afkoop zou de pensioenbestemming ondermijnen; daarom is alleen in beperkte uitzonderingen afkoop toegestaan."], ["Pensioen mag altijd worden afgekocht als de deelnemer dat wenst", "Een vrije afkoopmogelijkheid bestaat niet; dat zou het doel van een levenslange voorziening tenietdoen."], ["Afkoop is alleen verboden als de partner bezwaar maakt", "Het afkoopverbod geldt los van de wens van de partner; het is een wettelijke beperking."], ["Afkoop is volledig toegestaan zodra de deelnemer de AOW-leeftijd heeft bereikt en dat wenst", "Het bereiken van de AOW-leeftijd geeft geen algemeen afkooprecht; wel bestaat de beperkte optie van een bedrag ineens."]], "1j.5"],
["Een werkgever hanteert in zijn pensioenregeling een andere premie voor mannen dan voor vrouwen. Is dat toegestaan?", [["Nee, onderscheid naar geslacht in pensioenregelingen is niet toegestaan", "Gelijke behandeling van mannen en vrouwen geldt ook voor pensioen; premies en uitkeringen moeten sekseneutraal zijn."], ["Ja, omdat vrouwen gemiddeld langer leven", "Een verschil in levensverwachting rechtvaardigt geen onderscheid; de regeling moet gelijke behandeling waarborgen."], ["Ja, als het onderscheid in de cao is opgenomen", "Een cao kan wettelijke regels over gelijke behandeling niet opzij zetten."], ["Alleen bij een premieovereenkomst, niet bij een uitkeringsovereenkomst", "Het verbod op onderscheid naar geslacht geldt voor alle soorten pensioenovereenkomsten."]], "1h.11"],
["Joyce (36) werkt drie dagen per week als administratief medewerker bij een groothandel. Haar fulltime collega's nemen deel aan de pensioenregeling van de werkgever. Bij haar indiensttreding hoorde zij dat parttimers daarvan zijn uitgesloten. Er is geen bijzondere reden voor die uitsluiting gegeven. Wat is juist?", [["Dat is in strijd met het verbod op onderscheid naar arbeidsduur, tenzij objectief gerechtvaardigd", "Werkgevers mogen parttimers niet zonder objectieve rechtvaardiging uitsluiten van een pensioenregeling."], ["Dat mag, omdat de werkgever vrij is in de keuze wie aan de regeling deelnemen", "De werkgever is gebonden aan het verbod op onderscheid naar arbeidsduur."], ["Dat mag, zolang Joyce minder dan de helft van de normale arbeidsduur werkt", "Zo'n grens bestaat niet; ook kleine deeltijdbanen zijn beschermd."], ["Dat mag als de pensioenpremie voor parttimers anders te duur zou worden", "Alleen hogere kosten zijn in het algemeen geen objectieve rechtvaardiging."]], "1h.7"],
["Wie moet een nieuwe deelnemer na aanvang van de deelneming informeren over de hoofdlijnen van de pensioenregeling?", [["De pensioenuitvoerder, via een startbrief of vergelijkbare informatie", "De Pensioenwet legt de informatieplicht bij aanvang van de deelneming bij de uitvoerder, die de kern van de regeling toelicht."], ["De werknemer zelf, door het pensioenreglement op te vragen bij de afdeling HR", "De wet legt de informatieplicht juist bij de uitvoerder; de deelnemer hoeft hier niet zelf om te vragen."], ["De AFM, via een persoonlijke brief", "De AFM houdt toezicht op de communicatie, maar informeert deelnemers niet zelf over hun regeling."], ["Het UWV, bij de registratie van het dienstverband", "Het UWV voert werknemersverzekeringen uit en heeft geen rol bij informatie over de pensioenregeling."]], "1h.16"],
["Een werkgever biedt geen pensioenregeling aan. Wat moet hij volgens de Pensioenwet doen?", [["De werknemer informeren dat hij geen pensioenregeling heeft", "Zo weet de werknemer dat hij zelf moet zorgen voor aanvullend pensioen; de werkgever heeft een informatieplicht."], ["Een vervangende lijfrente voor de werknemer afsluiten", "De wet verplicht de werkgever niet om een lijfrente te regelen als hij geen pensioen biedt."], ["Een hogere bruto vergoeding betalen ter compensatie", "Er geldt geen wettelijke compensatieplicht; wel moet de werknemer worden geïnformeerd."], ["Niets, er bestaat in dat geval geen enkele verplichting", "Ook zonder pensioenregeling heeft de werkgever een informatieplicht tegenover de werknemer."]], "1h.16"],
["Het bouwbedrijf waar Ferry (44) als timmerman werkt, verkeert in financiële problemen. Het betaalt al enkele maanden de premie aan het bedrijfstakpensioenfonds niet. De achterstand is inmiddels behoorlijk opgelopen. Ferry en zijn collega's weten van niets. Wat moet het pensioenfonds bij een premieachterstand van enige omvang doen?", [["De deelnemers en de ondernemingsraad of werknemersvertegenwoordiging informeren", "Bij een premieachterstand van enige omvang moet de uitvoerder de deelnemers en de medezeggenschap op de hoogte brengen."], ["De pensioenopbouw van de deelnemers direct stopzetten tot de achterstand is ingelopen", "De pensioenaanspraken blijven bestaan; het fonds kan de premie bij de werkgever innen."], ["De achterstand verhalen op de werknemers door inhouding op hun loon", "De werkgever is premieschuldenaar; het fonds kan de schuld niet op de werknemers verhalen."], ["De zaak direct doorverwijzen naar het Kifid voor bindend advies", "Het Kifid is geen incasso- of toezichtsinstantie voor premieachterstanden."]], "1i.1"],
["Marco (39) werkt als lasser bij een machinefabriek. Zijn werkgever gaat failliet en de curator ontslaat alle werknemers. Achteraf blijkt dat de werkgever de pensioenpremie over de laatste maanden niet heeft afgedragen aan de verzekeraar. Marco is bang dat zijn opgebouwde pensioen nu verdwijnt. Wat kan hij verwachten?", [["Het UWV kan de achterstallige pensioenpremie over een beperkte periode overnemen", "Bij faillissement kan het UWV achterstallige premie over een beperkte periode betalen, zodat de opbouw over die periode wordt gerepareerd."], ["Zijn opgebouwde pensioen valt in de faillissementsboedel en wordt over de schuldeisers verdeeld", "De pensioenaanspraken zijn bij de uitvoerder ondergebracht en vallen niet in de boedel."], ["De verzekeraar laat alle opgebouwde aanspraken vervallen omdat er premie ontbreekt", "Het al opgebouwde pensioen blijft bestaan."], ["De curator mag het opgebouwde pensioen van Marco afkopen ten gunste van de schuldeisers", "De curator heeft geen zeggenschap over het bij de uitvoerder ondergebrachte pensioen."]], "1h.19"],
["De drukkerij van directeur Sandra (49) heeft 80 werknemers en een ondernemingsraad. Er is geen cao van toepassing. Sandra wil een nieuwe pensioenregeling bij een verzekeraar invoeren. De adviseur bereidt het voorstel voor. Welk recht heeft de ondernemingsraad bij de invoering?", [["Instemmingsrecht", "Als pensioen niet in een cao is geregeld, heeft de OR instemmingsrecht bij invoering, wijziging of intrekking van een pensioenregeling."], ["Alleen informatierecht achteraf", "De WOR geeft de OR bij pensioenregelingen meer dan alleen informatie achteraf."], ["Een vetorecht op de keuze van ieder afzonderlijk beleggingsfonds", "Het instemmingsrecht ziet op de regeling, niet op elk afzonderlijk beleggingsfonds."], ["Geen enkel recht, pensioen is een zaak van de uitvoerder", "Juist bij de pensioenregeling zelf heeft de OR een belangrijke rol."]], "1g.6"],
["Volgens welk uitgangspunt moet een pensioenfonds zijn vermogen beleggen?", [["De prudent-personregel: zorgvuldig en in het belang van de deelnemers en gepensioneerden", "De Pensioenwet vereist dat het fonds belegt zoals een voorzichtig handelend persoon zou doen, met aandacht voor risico en spreiding."], ["Uitsluitend in Nederlandse staatsobligaties", "De wet schrijft geen specifieke beleggingscategorie voor; het gaat om een zorgvuldige, gespreide belegging."], ["Zo dat het hoogst mogelijke rendement wordt behaald, ongeacht de risico's voor de deelnemers", "Risico moet passen bij de verplichtingen; maximaal rendement zonder oog voor risico is niet prudent."], ["Volgens de beleggingswensen van de werkgever", "Het fondsbestuur belegt in het belang van alle belanghebbenden, niet naar de wens van de werkgever."]], "1f.3"],
["Wat drukt de dekkingsgraad van een pensioenfonds uit?", [["De verhouding tussen het vermogen van het fonds en de waarde van de pensioenverplichtingen", "Een dekkingsgraad van 100% betekent dat het vermogen precies gelijk is aan de waarde van de toegezegde pensioenen."], ["Het percentage deelnemers dat een partnerpensioen heeft", "De dekkingsgraad is een financiële maatstaf, geen maat voor de dekking van nabestaandenrisico's."], ["De verhouding tussen de premie-inkomsten en de uitkeringen die het fonds in een jaar betaalt", "Die kasstroomverhouding zegt weinig over de financiële positie; de dekkingsgraad vergelijkt vermogen met verplichtingen."], ["Het deel van het salaris waarover pensioen wordt opgebouwd", "Dat is de pensioengrondslag na aftrek van de franchise, geen begrip voor de financiële positie van het fonds."]], "1h.3"],
["Wat betekent voorwaardelijke toeslagverlening (indexatie) in een uitkeringsregeling bij een pensioenfonds?", [["Het fonds verhoogt pensioenen alleen als de financiële positie dat toelaat; er is geen recht op", "Bij voorwaardelijke toeslagen hangt de verhoging af van het fondsbeleid en de dekkingsgraad, en moet dat duidelijk worden gecommuniceerd."], ["Het pensioen stijgt elk jaar gegarandeerd mee met de prijsinflatie, zoals die door het CBS wordt gemeten", "Een gegarandeerde verhoging is onvoorwaardelijke indexatie; die is duur en moet volledig worden gefinancierd."], ["Het pensioen wordt alleen verhoogd als de deelnemer bijbetaalt", "Toeslagen worden betaald uit het fondsrendement of een daarvoor bestemde reserve, niet uit een bijdrage van de deelnemer."], ["De werkgever is verplicht een tekort voor indexatie bij te storten", "Bij voorwaardelijke toeslagverlening bestaat geen bijstortingsplicht van de werkgever."]], "1h.2"],
["Een pensioenfonds dat nog niet is overgestapt naar het nieuwe stelsel heeft langdurig een te lage dekkingsgraad. Welke maatregel kan het fonds dan als laatste middel nemen?", [["Het korten van pensioenaanspraken en -rechten", "Als herstel binnen de wettelijke termijnen niet lukt, kan een fonds onder strikte voorwaarden de pensioenen verlagen."], ["De pensioenen van gepensioneerden tijdelijk opschorten", "Een opschorting van uitkeringen is geen wettelijk instrument; het fonds kan wel korten."], ["De deelnemers verplichten een eenmalige bijstorting te doen", "Deelnemers kunnen niet worden verplicht bij te storten om een tekort van het fonds op te vangen."], ["De werkgever dwingen de onderneming in te brengen in het fonds", "De werkgever kan niet worden gedwongen zijn onderneming in te brengen; korting is het wettelijke sluitstuk."]], "1h.2"],
["Wat is een kenmerkend nadeel van een eindloonregeling voor de werkgever of het fonds ten opzichte van een middelloonregeling?", [["Bij een salarisverhoging moet het pensioen over alle verstreken dienstjaren worden opgehoogd", "In een eindloonregeling is het laatste salaris de basis voor alle jaren, waardoor een loonsverhoging tot dure inhaalfinanciering leidt."], ["Er wordt in een eindloonregeling geen partnerpensioen opgebouwd", "Ook eindloonregelingen kunnen partnerpensioen bevatten; dat staat los van de systematiek."], ["De werknemer draagt in een eindloonregeling het volledige beleggingsrisico over zijn ingelegde premies", "Het beleggingsrisico ligt bij de deelnemer in een premieregeling, niet in een eindloonregeling."], ["Een eindloonregeling is fiscaal niet toegestaan", "Eindloonregelingen waren binnen het Witteveenkader toegestaan; het nadeel is vooral financieel."]], "1h.2"],
["Sophie (31) is net in dienst bij een architectenbureau. Op haar loonstrook ziet zij dat er elke maand een eigen bijdrage voor de pensioenregeling wordt ingehouden. Haar werkgever betaalt de rest van de premie. Sophie vraagt of zij deze eigen bijdrage in haar aangifte inkomstenbelasting mag aftrekken. Wat is juist?", [["Nee, de bijdrage wordt al op haar fiscale loon in mindering gebracht, zodat zij er geen loonbelasting over betaalt", "De werknemersbijdrage voor een fiscaal zuivere pensioenregeling verlaagt direct het belaste loon; een tweede aftrek is er niet."], ["Ja, zij mag de bijdrage in haar aangifte aftrekken als uitgave voor inkomensvoorzieningen", "Die aftrekpost geldt voor lijfrentepremie, niet voor de eigen bijdrage aan werkgeverspensioen."], ["Nee, de bijdrage is belast, maar de latere pensioenuitkering is daardoor onbelast", "De omkeerregel werkt andersom: de bijdrage is onbelast en de uitkering belast."], ["Nee, de bijdrage valt als vermogen in box 3 en is daar vrijgesteld", "Pensioenbijdragen vallen niet in box 3."]], "1i.9"],
["Arend is 64 jaar en werkt al 25 jaar als vrachtwagenchauffeur. Het lange rijden valt hem steeds zwaarder. Hij wil daarom twee dagen per week minder werken en dat inkomensverlies opvangen met zijn pensioen. Zijn AOW-leeftijd ligt nog ongeveer drie jaar later. Wat is in het algemeen juist?", [["Veel regelingen kennen deeltijdpensioen: een deel van het pensioen gaat in en hij werkt deels door", "Deeltijdpensioen maakt het mogelijk een deel van het pensioen eerder te laten ingaan bij minder werken."], ["Dat kan niet, want het ouderdomspensioen moet volgens de Pensioenwet altijd in één keer volledig ingaan", "Deeltijdpensioen is in veel regelingen juist mogelijk."], ["Dat kan alleen als hij ook zijn AOW gedeeltelijk laat ingaan", "De AOW kan niet gedeeltelijk of eerder ingaan."], ["Dat kan, maar het ingegane deel van het pensioen moet dan als bedrag ineens worden afgekocht", "Het ingegane deel wordt als periodieke uitkering betaald, niet verplicht afgekocht."]], "1g.5"],
["Wat is het gevolg voor de hoogte van de uitkering als een deelnemer zijn ouderdomspensioen eerder laat ingaan dan de pensioendatum in de regeling?", [["De uitkering wordt lager, omdat er minder is opgebouwd en langer wordt uitgekeerd", "Vervroegen wordt actuarieel herrekend: minder opbouwjaren en een langere uitkeringsduur leiden tot een lagere jaarlijkse uitkering."], ["De uitkering blijft gelijk, alleen de AOW wordt lager", "De AOW verandert niet; het eerder ingaande aanvullend pensioen wordt wel omgerekend."], ["De uitkering wordt hoger, omdat de deelnemer korter heeft gewerkt en dus minder lang premie betaalde", "Korter werken betekent juist minder opbouw en dus een lagere uitkering."], ["Er volgt een boete die de werknemer aan de werkgever betaalt", "Er is geen boete; het effect zit volledig in de actuariële herrekening van het pensioen."]], "1g.5"],
["Hanneke (67) gaat met pensioen na een loopbaan als ziekenhuisapotheker. Zij is gehuwd met Karel, die als zelfstandige weinig eigen pensioen heeft opgebouwd. Hanneke wil dat Karel goed verzorgd achterblijft als zij eerder overlijdt. Haar eigen ouderdomspensioen is ruim voldoende. Welke keuze kan het nabestaandenpensioen voor Karel verhogen?", [["Uitruil van een deel van haar ouderdomspensioen naar extra partnerpensioen", "Door uitruil wordt haar ouderdomspensioen lager en het partnerpensioen voor Karel hoger."], ["Een hoog-laagconstructie, waarbij zij de eerste jaren een hogere uitkering krijgt", "Hoog-laag verandert de verdeling in de tijd van haar eigen pensioen, niet het partnerpensioen."], ["Een bedrag ineens van 10% van haar pensioen op de pensioendatum", "Een bedrag ineens verlaagt haar pensioen en verhoogt het partnerpensioen niet."], ["De ingangsdatum van haar pensioen een jaar vervroegen", "Vervroegen verlaagt haar uitkering en verhoogt het partnerpensioen niet."]], "1g.13"],
["Wat houdt een hoog-laagconstructie in bij de ingang van het ouderdomspensioen?", [["Eerst een hogere en daarna een lagere uitkering, binnen een wettelijke maximale verhouding", "De fiscale regels begrenzen het verschil tussen de hoge en de lage uitkering; zo blijft er levenslang voldoende pensioen over."], ["De pensioenuitkering stijgt jaarlijks met een vast percentage", "Een oplopende uitkering is juist het omgekeerde; bij hoog-laag gaat de uitkering na een periode omlaag."], ["De partner ontvangt eerst een hoog en later een laag partnerpensioen", "Hoog-laag ziet op het ouderdomspensioen van de deelnemer, niet op het partnerpensioen."], ["De deelnemer krijgt een hoog bedrag ineens uitbetaald en daarna geen periodieke uitkering meer", "Een volledige uitbetaling ineens is geen hoog-laag en is niet toegestaan; de uitkering blijft levenslang."]], "1g.5"],
["Ronald (47) nam deel aan een traditionele premieregeling bij een verzekeraar en had al een flink beleggingskapitaal opgebouwd. In de regeling was geen restitutiedekking opgenomen. Ronald overlijdt plotseling. Zijn broer, die zijn enige erfgenaam is, vraagt de verzekeraar om uitbetaling van het kapitaal. Wat gebeurt er in zo'n regeling doorgaans met het opgebouwde kapitaal?", [["Het vervalt doorgaans aan de uitvoerder of wordt gebruikt voor nabestaandenpensioen", "Zonder restitutiedekking keert het kapitaal niet uit aan erfgenamen; het valt vrij of wordt volgens de regeling ingezet voor nabestaandenpensioen."], ["Het wordt in contanten aan de erfgenamen uitbetaald volgens de wettelijke verdeling of het testament", "Uitbetaling aan erfgenamen vraagt juist een restitutiedekking."], ["Het wordt overgemaakt naar de werkgever van Ronald", "De werkgever heeft geen recht op het pensioenkapitaal."], ["Het wordt verplicht omgezet in een lijfrente voor de broer als erfgenaam", "Er bestaat geen verplichte omzetting in een lijfrente voor erfgenamen."]], "1i.8"],
["Bianca (45) is teamleider in een distributiecentrum en neemt deel aan de pensioenregeling van haar werkgever. Na een ernstige rugaandoening wordt zij na twee jaar ziekte voor 80% arbeidsongeschikt verklaard. In de regeling is premievrijstelling bij arbeidsongeschiktheid meeverzekerd. Zij vraagt wat dat voor haar pensioen betekent. Wat is juist?", [["Haar opbouw loopt door zonder dat voor het arbeidsongeschikte deel nog premie wordt betaald", "Bij premievrijstelling neemt de uitvoerder de premie voor het arbeidsongeschikte deel over, zodat de opbouw doorloopt."], ["Zij krijgt een levenslange aanvullende uitkering van de uitvoerder ter vervanging van haar gederfde salaris", "Dat is een arbeidsongeschiktheidspensioen of WIA-excedentdekking, niet premievrijstelling."], ["Haar pensioenopbouw stopt volledig tot zij is hersteld", "Premievrijstelling zorgt er juist voor dat de opbouw doorloopt."], ["Zij hoeft later geen belasting meer te betalen over haar pensioenuitkering", "Premievrijstelling heeft geen invloed op de belastingheffing over de uitkering."]], "1i.4"],
["Wat is het doel van een WIA-hiaat- of WIA-excedentverzekering binnen een arbeidsvoorwaardenpakket?", [["Het inkomensverlies bij arbeidsongeschiktheid aanvullen dat niet door de WIA wordt gedekt", "De WIA dekt maar een deel van het loon en is gemaximeerd; deze verzekeringen vullen het gat of het deel boven het maximumdagloon aan."], ["Het overnemen van de pensioenpremie door de uitvoerder zolang de werknemer arbeidsongeschikt is", "Dat doet de premievrijstelling bij arbeidsongeschiktheid in de pensioenregeling."], ["Een uitkering aan nabestaanden bij overlijden van de werknemer", "Overlijdensrisico wordt gedekt met partnerpensioen, Anw-hiaatpensioen of een ORV, niet met een WIA-verzekering."], ["De AOW verhogen bij vroegtijdige arbeidsongeschiktheid", "De AOW wordt niet verhoogd door arbeidsongeschiktheid; het gaat om aanvulling van het inkomen vóór de AOW-leeftijd."]], "1i.8"],
["Welke informatie moet een werknemer bij beëindiging van de deelneming, bijvoorbeeld bij uitdiensttreding, in ieder geval van de uitvoerder krijgen?", [["Een opgave van de opgebouwde aanspraken en informatie over de mogelijkheid van waardeoverdracht", "Bij einde deelneming moet de gewezen deelnemer weten wat hij heeft opgebouwd en welke keuzes hij heeft, zoals waardeoverdracht."], ["Een offerte voor een lijfrente bij een andere aanbieder waarin het opgebouwde pensioen kan worden gestort", "De uitvoerder hoeft geen derdepijlerofferte te verstrekken; hij informeert over het opgebouwde pensioen."], ["Een automatische afkoopsom van het opgebouwde pensioen", "Uitdiensttreding geeft geen recht op afkoop; het pensioen blijft premievrij staan of gaat over via waardeoverdracht."], ["Een overzicht van de AOW-opbouw over de diensttijd", "De AOW-opbouw is een zaak van de SVB, niet van de pensioenuitvoerder."]], "1h.16"],
["Wat betekent de overstap naar uitsluitend premieovereenkomsten onder de Wtp voor de werkgever?", [["Hij betaalt een vooraf afgesproken premie en heeft geen verplichting om tekorten aan te vullen", "In een premieovereenkomst is de verplichting van de werkgever beperkt tot de premie; een bijstortingsplicht bij tekorten past daar niet bij."], ["Hij garandeert voortaan een vaste uitkering op de pensioendatum", "Een gegarandeerde uitkering hoort bij een uitkeringsovereenkomst; die verdwijnt juist voor nieuwe opbouw."], ["Hij moet de premie elk jaar aanpassen aan de dekkingsgraad", "In het nieuwe stelsel is een stabiele premie het uitgangspunt; de dekkingsgraad als sturingsmiddel verdwijnt."], ["Hij draagt voortaan zelf het volledige beleggingsrisico over de pensioenvermogens van alle deelnemers", "Het beleggingsrisico ligt in een premieregeling bij de deelnemers, eventueel collectief gedeeld."]], "1f.2"],
["Wie stelt bij de transitie naar het nieuwe pensioenstelsel het transitieplan op voor een werkgeversregeling?", [["De werkgever, samen met de werknemers of hun vertegenwoordigers (sociale partners)", "In het transitieplan leggen sociale partners de nieuwe regeling, de keuze over invaren en de compensatie vast."], ["De AFM, als toezichthouder op de pensioencommunicatie en de uitvoering van pensioenregelingen", "De AFM houdt toezicht op informatie, maar stelt geen plannen op voor individuele regelingen."], ["De SVB, omdat zij de AOW uitvoert", "De SVB heeft geen rol bij de transitie van het aanvullend pensioen."], ["Iedere deelnemer afzonderlijk, via een persoonlijke keuze", "De transitie is een collectief proces; deelnemers stellen geen eigen transitieplan op."]], "1h.13"],
["Wat is de rol van het implementatieplan bij de transitie naar het nieuwe stelsel?", [["Daarin beschrijft de uitvoerder hoe hij de nieuwe regeling en de overgang uitvoert", "Het implementatieplan volgt op het transitieplan van sociale partners en laat zien hoe de uitvoerder de afspraken praktisch invult."], ["Daarin kiezen deelnemers individueel of zij met hun opgebouwde pensioen willen invaren", "Er bestaat geen individuele keuze over invaren; het besluit wordt collectief genomen."], ["Daarin legt de Belastingdienst de nieuwe fiscale grenzen vast", "De fiscale grenzen staan in de wet; het implementatieplan is een document van de uitvoerder."], ["Daarin wordt de AOW-leeftijd voor de deelnemers vastgesteld", "De AOW-leeftijd wordt door de wet bepaald, los van de pensioentransitie."]], "1h.13"],
["Heeft een deelnemer in een solidaire premieregeling een eigen, persoonlijk pensioenvermogen?", [["Ja, iedere deelnemer krijgt een toegedeeld pensioenvermogen, terwijl collectief wordt belegd", "Ook in de solidaire regeling is er een toegedeeld pensioenvermogen per deelnemer; het rendement wordt via een collectief toedelingssysteem verdeeld."], ["Nee, er is alleen een collectieve pot zonder enige toedeling van vermogen aan individuele deelnemers", "Het nieuwe stelsel maakt het vermogen per deelnemer juist inzichtelijk, ook in de solidaire variant."], ["Nee, de deelnemer bouwt een aanspraak op een vaste uitkering op", "Een vaste uitkeringsaanspraak hoort bij het oude stelsel; in een premieregeling is er een pensioenvermogen."], ["Ja, en hij mag dat vermogen zelf vrij beleggen", "Vrije individuele beleggingskeuzes passen bij de flexibele regeling, niet bij de collectief belegde solidaire regeling."]], "1f.3"],
["Wat is het doel van het beschermingsrendement in de solidaire premieregeling?", [["De pensioenen van vooral oudere deelnemers beschermen tegen schommelingen door renteveranderingen", "Het beschermingsrendement beweegt mee met de rente, zodat de verwachte uitkering voor deelnemers dicht bij pensionering stabieler blijft."], ["Het bieden van een gegarandeerde minimumuitkering aan alle deelnemers, ongeacht de beleggingsresultaten", "Het nieuwe stelsel kent geen garanties; het beschermingsrendement dempt alleen renterisico."], ["De werkgever beschermen tegen premiestijgingen", "Het beschermingsrendement betreft de toedeling van rendement aan deelnemers, niet de premiehoogte."], ["Jongeren beschermen tegen een te lage premie", "Het beschermingsrendement is vooral gericht op deelnemers dichter bij of in de uitkeringsfase."]], "1f.3"],
["Waarvoor dient een periodiek risicopreferentieonderzoek bij een pensioenuitvoerder?", [["Om de risicohouding van deelnemers vast te stellen, zodat het beleggingsbeleid daarbij past", "In het nieuwe stelsel moet het beleid passen bij de risicobereidheid van de deelnemers; die wordt periodiek onderzocht."], ["Om de gezondheid van deelnemers te beoordelen voor de premie van het partnerpensioen op risicobasis", "Medische selectie is niet toegestaan; het onderzoek gaat over risicobereidheid bij beleggen."], ["Om te bepalen welke deelnemers mogen kiezen voor afkoop", "Afkoop is wettelijk begrensd en wordt niet bepaald door een risicopreferentieonderzoek."], ["Om de premie per deelnemer individueel vast te stellen", "De premie is in de regeling vastgelegd en wordt niet per deelnemer op basis van risicohouding bepaald."]], "1f.1"],
["Hans (58) neemt deel aan een flexibele premieregeling onder de Wet toekomst pensioenen. Hij heeft nooit gekeken naar de beleggingskeuzes die zijn uitvoerder aanbiedt. Nu zijn pensioen dichterbij komt, maakt hij zich zorgen over koersdalingen. Hij vraagt hoe zijn pensioenvermogen wordt belegd als hij zelf niets kiest. Wat is juist?", [["Volgens de standaard lifecycle, waarbij het risico afneemt naarmate de pensioendatum nadert", "Zonder eigen keuze wordt belegd volgens de standaardlifecycle, die het risico afbouwt richting pensioendatum."], ["Het wordt tot de pensioendatum volledig in aandelen belegd", "Een lifecycle bouwt het risico juist af; volledig aandelen tot het einde past daar niet bij."], ["Het blijft onbelegd op een spaarrekening staan tot hij een keuze maakt", "In een premieregeling wordt het vermogen belegd, ook zonder eigen keuze."], ["Het wordt automatisch overgezet naar de solidaire regeling, omdat hij geen keuze maakte", "Het niet kiezen van een beleggingsprofiel leidt niet tot een ander type regeling."]], "1f.1"],
["Wat is een kenmerk van de solidariteitsreserve in de solidaire premieregeling?", [["Zij wordt gevuld uit premie of overrendement en kan tegenvallers dempen", "De reserve deelt risico's tussen generaties: in goede tijden wordt zij gevuld, in slechte tijden kan zij worden aangesproken."], ["Zij is een persoonlijke spaarpot die bij pensionering als extra bedrag wordt uitgekeerd", "De reserve is collectief en niet aan individuele deelnemers toegedeeld."], ["Zij wordt gevuld door een verplichte bijdrage van de AOW", "De AOW staat los van het aanvullend pensioen en draagt niets bij aan een solidariteitsreserve."], ["Zij garandeert dat pensioenen nooit kunnen dalen", "De reserve dempt schommelingen, maar biedt geen garantie tegen verlaging."]], "1f.3"],
["Een pensioenuitvoerder gaat rekenen met een nieuwe overlevingstafel waarin de verwachte levensduur hoger is dan in de oude tafel. Wat is daarvan in het algemeen het gevolg?", [["De benodigde voorzieningen en de inkoop van levenslange uitkeringen worden duurder", "Als deelnemers naar verwachting langer leven, moet er langer worden uitgekeerd en is meer vermogen nodig."], ["De voorzieningen dalen, omdat er minder deelnemers overlijden vóór hun pensioendatum", "Een hogere levensverwachting verhoogt per saldo de kosten van levenslange uitkeringen."], ["Er is geen gevolg, omdat overlevingstafels alleen voor de AOW worden gebruikt", "Overlevingstafels zijn juist een belangrijke grondslag voor aanvullend pensioen."], ["De uitkeringen worden automatisch verhoogd met de extra levensjaren", "Een nieuwe tafel verhoogt de kosten, niet automatisch de hoogte van de uitkering."]], "1h.22"],
["Wat is de pensioengrondslag in een pensioenregeling?", [["Het pensioengevend salaris verminderd met de franchise", "Over de pensioengrondslag wordt het pensioen of de premie berekend; de franchise houdt rekening met de AOW."], ["Het volledige brutosalaris inclusief alle vergoedingen", "Niet alle looncomponenten zijn pensioengevend en de franchise wordt in mindering gebracht."], ["Het bedrag dat de werknemer zelf aan premie betaalt", "De eigen bijdrage is een deel van de premie, niet de grondslag waarover pensioen wordt opgebouwd."], ["Het nettosalaris na loonheffing", "Pensioen wordt berekend over een brutogrondslag, niet over het nettoloon."]], "1h.3"],
["Wat bedoelt men met een onzuivere handeling met een pensioenaanspraak, zoals afkoop buiten de wettelijke uitzonderingen?", [["Een handeling in strijd met de fiscale voorwaarden, waardoor de waarde als loon wordt belast", "Bij een onzuivere handeling vervalt de fiscale facilitering met terugwerkende kracht; daarom is de waarde belast en geldt revisierente."], ["Een handeling die alleen gevolgen heeft voor de hoogte van de premie in het volgende kalenderjaar", "De gevolgen zijn veel zwaarder: de volledige waarde van de aanspraak wordt belast."], ["Een handeling waarbij de uitvoerder een fout maakt in de berekening", "Het begrip ziet op fiscaal ongeoorloofd gebruik van de aanspraak, niet op administratieve fouten."], ["Een handeling die alleen strafrechtelijke gevolgen heeft", "Het gevolg is fiscaal: heffing over de waarde, niet primair een strafrechtelijke sanctie."]], "1j.5"],
["Hoe hoog is de revisierente die bij een onzuivere handeling met een pensioen- of lijfrenteaanspraak kan worden geheven?", [["20% van de waarde van de aanspraak, met uitzonderingen", "Revisierente compenseert het belastingvoordeel uit het verleden en bedraagt in beginsel 20%."], ["10% van de waarde van de aanspraak", "10% kent u van het maximale bedrag ineens bij pensioeningang, niet van de revisierente."], ["52% van de waarde van de aanspraak", "52% is het tarief van onder meer de pseudo-eindheffing bij een RVU, niet de revisierente."], ["Er geldt een vast bedrag per jaar dat de aanspraak bestond", "Revisierente is een percentage van de waarde, niet een vast bedrag per jaar."]], "1j.5"],
["Hoe wordt de werkgeverspremie voor een fiscaal zuivere pensioenregeling bij de werknemer behandeld?", [["De premie behoort niet tot het belaste loon van de werknemer", "Door de omkeerregel is de aanspraak vrijgesteld; belasting volgt pas over de uitkering."], ["De premie wordt als loon in natura belast in box 1", "Dat gebeurt alleen bij een bovenmatige of onzuivere regeling, niet bij een regeling binnen het Witteveenkader."], ["De premie valt bij de werknemer in box 3 als vermogen", "Pensioenaanspraken zijn geen box 3-bezit; zij vallen onder de omkeerregel in de loonsfeer."], ["De werknemer mag de werkgeverspremie in zijn aangifte aftrekken", "De werknemer betaalt deze premie niet zelf en kan haar daarom niet aftrekken."]], "1g.10"],
["Iemand ontvangt een ouderdomspensioen van een pensioenfonds. Hoe wordt die uitkering fiscaal gekwalificeerd?", [["Als loon uit vroegere dienstbetrekking, belast in box 1", "Pensioen is uitgesteld loon; de uitvoerder houdt loonheffing in en de uitkering valt in box 1."], ["Als inkomen uit aanmerkelijk belang in box 2", "Box 2 betreft voordelen uit aanmerkelijk belang, zoals dividend uit een eigen bv."], ["Als voordeel uit sparen en beleggen in box 3", "Box 3 belast vermogen; periodieke pensioenuitkeringen vallen in box 1."], ["Als onbelaste uitkering, omdat de premie al belast was", "Dat geldt voor nettopensioen; bij een gewone regeling was de premie juist onbelast."]], "1g.10"],
["Welke rol speelt de pensioenaangroei (factor A) bij de fiscale ruimte voor lijfrente?", [["De pensioenaangroei over het voorgaande jaar verlaagt de jaarruimte", "Wie via de werkgever al pensioen opbouwt, heeft minder fiscale ruimte nodig; daarom wordt factor A in de jaarruimteberekening meegenomen."], ["De pensioenaangroei verhoogt de jaarruimte", "Meer werkgeverspensioen betekent juist minder pensioentekort en dus minder jaarruimte."], ["Factor A bepaalt de hoogte van de AOW", "De AOW hangt af van woonjaren en leefsituatie, niet van factor A."], ["Factor A geldt alleen voor de reserveringsruimte van zelfstandigen", "Factor A is juist relevant voor werknemers die pensioen opbouwen en verlaagt hun jaarruimte."]], "1g.10"],
["Welke eis geldt voor een algemeen pensioenfonds (apf) voordat het pensioenregelingen mag uitvoeren?", [["Het moet beschikken over een vergunning van DNB", "Een apf mag pas pensioenregelingen uitvoeren als DNB een vergunning heeft verleend."], ["Het moet door de minister verplicht zijn gesteld voor een bedrijfstak", "Een verplichtstelling hoort bij een bedrijfstakpensioenfonds, niet bij een apf."], ["Het moet zijn opgericht als naamloze vennootschap met aandeelhouders", "Een pensioenfonds, ook een apf, is een stichting."], ["Het moet bij de AFM zijn ingeschreven als financieel adviseur", "Een apf is een pensioenuitvoerder en geen adviseur."]], "1h.23"],
["Mustafa (45) heeft een eenmanszaak als installateur en is ondernemer voor de inkomstenbelasting. Hij heeft nooit bij een werkgever gewerkt en bouwt geen pensioen op. Zijn adviseur wil berekenen hoeveel lijfrentepremie hij binnen de jaarruimte kan aftrekken. Daarvoor is zijn premiegrondslag nodig. Wat telt mee voor de premiegrondslag van Mustafa?", [["Onder meer zijn winst uit onderneming, naast eventueel loon of resultaat uit overige werkzaamheden", "De premiegrondslag bestaat uit onder meer winst uit onderneming, loon en resultaat uit overige werkzaamheden."], ["Alleen loon uit dienstbetrekking, zodat een ondernemer geen jaarruimte heeft", "Ook ondernemers hebben jaarruimte; hun winst telt mee."], ["Zijn spaargeld en beleggingen in box 3", "Vermogen in box 3 telt niet mee voor de premiegrondslag."], ["Alleen het dividend dat hij ontvangt uit een aanmerkelijk belang in box 2", "Inkomen uit aanmerkelijk belang telt niet mee voor de premiegrondslag."]], "1g.10"],
["Monique (44) werkt bij een werkgever die onder de Wet toekomst pensioenen een nieuwe premieregeling heeft ingevoerd. Zij woont samen met haar partner en heeft twee jonge kinderen. In de regeling is het partnerpensioen vóór de pensioendatum verzekerd op risicobasis. Monique vraagt hoe hoog dat partnerpensioen fiscaal maximaal mag zijn. Wat is juist?", [["Maximaal 50% van het pensioengevend salaris", "Onder de Wtp is het partnerpensioen op risicobasis vóór de pensioendatum fiscaal begrensd op 50% van het pensioengevend salaris."], ["Maximaal 70% van het ouderdomspensioen dat zij bij doorwerken tot de pensioendatum zou opbouwen", "De koppeling aan 70% van het ouderdomspensioen hoort bij partnerpensioen dat na de pensioendatum ingaat, niet bij risicodekking vóór die datum."], ["Maximaal 100% van het pensioengevend salaris", "Zo'n hoog partnerpensioen past niet binnen het fiscale kader."], ["Er geldt geen fiscale grens, omdat het om een risicodekking gaat", "Ook voor partnerpensioen op risicobasis gelden fiscale maxima."]], "1i.5"],
["Saskia heeft een lijfrenteverzekering die binnenkort expireert. Zij wil het kapitaal gebruiken voor een uitkering bij een andere aanbieder. Kan dat zonder fiscale gevolgen?", [["Ja, zij kan het kapitaal rechtstreeks overdragen naar een andere toegestane aanbieder", "Een rechtstreekse overdracht tussen toegestane aanbieders is geen afkoop; zo kan Saskia het beste uitkeringstarief zoeken."], ["Nee, de aankoop van de uitkering moet altijd plaatsvinden bij de verzekeraar waar zij heeft opgebouwd", "Er geldt geen verplichting om bij dezelfde aanbieder te blijven; overdracht naar een andere aanbieder is toegestaan."], ["Alleen als zij het kapitaal eerst op haar eigen rekening laat storten", "Uitbetaling aan Saskia zelf zou als afkoop worden belast; de overdracht moet rechtstreeks plaatsvinden."], ["Ja, maar dan wordt het kapitaal in box 3 belast", "Bij een correcte overdracht blijft het kapitaal in de lijfrentesfeer en vrijgesteld in box 3."]], "1g.10"],
["Wat houdt het prijsgeven van een pensioenaanspraak in, en wat is fiscaal het gevolg?", [["Afstand doen van (een deel van) de aanspraak, wat als onzuivere handeling tot belastingheffing kan leiden", "Prijsgeven is het geheel of gedeeltelijk afstand doen van een aanspraak; fiscaal wordt dat in beginsel behandeld als een onzuivere handeling."], ["Het overdragen van de aanspraak naar een andere uitvoerder via waardeoverdracht, zonder enige fiscale gevolgen", "Waardeoverdracht is geen prijsgeven; de aanspraak blijft dan behouden."], ["Het tijdelijk premievrij maken van de opbouw tijdens ouderschapsverlof", "Het onderbreken van opbouw is geen afstand doen van al opgebouwde aanspraken."], ["Het omzetten van partnerpensioen in ouderdomspensioen bij pensionering, belast als loon", "Uitruil binnen de regels is een toegestane keuze en geen prijsgeven."]], "1j.5"],
["Waarom moet een dga met een meerderheidsbelang in zijn bv bijzondere aandacht besteden aan het risico van arbeidsongeschiktheid?", [["Omdat hij doorgaans niet verplicht verzekerd is voor de WIA en zelf een voorziening moet treffen", "Een dga die niet tegen zijn wil kan worden ontslagen, is meestal niet verzekerd voor de werknemersverzekeringen."], ["Omdat zijn AOW vervalt als hij voor zijn AOW-leeftijd arbeidsongeschikt wordt", "Arbeidsongeschiktheid heeft geen invloed op het recht op AOW."], ["Omdat zijn bv bij zijn arbeidsongeschiktheid wettelijk moet worden geliquideerd", "Er bestaat geen plicht om een bv bij arbeidsongeschiktheid van de dga te liquideren."], ["Omdat het UWV voor dga's een hogere WIA-uitkering vaststelt die de bv moet terugbetalen", "Zo'n regeling bestaat niet; meestal heeft een dga juist geen recht op WIA."]], "1j.15"],
["Ruud (52) is dga van een adviesbureau en zijn bv heeft veel vrije liquiditeit. Hij heeft nog jaarruimte voor lijfrente over. Ruud wil de lijfrente laten opbouwen in zijn eigen bv, zodat het geld binnen zijn onderneming blijft. Zijn boekhouder twijfelt of dat fiscaal kan. Is dit mogelijk?", [["Nee, alleen een toegestane verzekeraar, bank of beleggingsinstelling mag een fiscale lijfrente aanbieden", "De fiscale lijfrente moet bij een in de wet genoemde aanbieder worden ondergebracht; de eigen bv hoort daar niet bij."], ["Ja, als de bv voldoende vermogen heeft om de lijfrente later uit te keren", "Het vermogen van de bv is niet bepalend; de bv is geen toegestane aanbieder."], ["Ja, mits de lijfrente als aparte verplichting in de jaarrekening van de bv wordt opgenomen", "Een vermelding in de jaarrekening maakt de bv nog geen toegestane lijfrenteaanbieder."], ["Alleen als zijn partner schriftelijk toestemming geeft voor de opbouw in de bv", "Toestemming van de partner verandert niets aan de eisen voor de aanbieder."]], "1j.20"],
["Gert heeft een restaurant met een pensioenregeling bij een verzekeraar; er geldt geen verplichtstelling of cao. Zijn nieuwe kok Sven (26) wil niet meedoen, omdat hij liever nu meer netto overhoudt. Gert wil dat goedvinden, maar twijfelt over de gevolgen. Later zou Sven of zijn partner kunnen stellen dat hij nooit goed is voorgelicht. Waarop moet de adviseur Gert wijzen?", [["Dat hij de voorlichting en de keuze van Sven schriftelijk vastlegt, om latere claims te voorkomen", "Bij afstand van deelname is een getekende verklaring met uitleg over de gevolgen belangrijk om aansprakelijkheid te beperken."], ["Dat een mondelinge afspraak volstaat, omdat Sven later nooit meer een claim kan indienen", "Zonder schriftelijke vastlegging kan Gert moeilijk bewijzen dat Sven goed was voorgelicht."], ["Dat hij Sven wettelijk het volledige premiebedrag als extra brutoloon moet uitbetalen", "Een wettelijke plicht om de premie als loon uit te betalen bestaat niet."], ["Dat Sven automatisch weer deelneemt zodra hij een partner krijgt", "Er is geen automatische deelname bij het krijgen van een partner."]], "1i.2"],
["Iris (38) is jurist bij een bank en bouwt via haar werkgever pensioen op tot de aftoppingsgrens. Haar salaris ligt daar ruim boven. Haar werkgever biedt geen nettopensioen aan. Iris wil toch extra sparen voor haar oude dag over het inkomen boven de grens. Welke derdepijlermogelijkheid kan bij haar situatie aansluiten?", [["Een nettolijfrente, met inleg uit netto-inkomen en een box 3-vrijstelling tijdens de opbouw", "De nettolijfrente is bedoeld voor wie boven de aftoppingsgrens verdient en geen nettopensioen kan opbouwen."], ["Een lijfrente waarvan de premie over het hele inkomen boven de aftoppingsgrens aftrekbaar is", "Boven de aftoppingsgrens is er juist geen fiscale aftrek voor oudedagsopbouw."], ["Een tweede werkgeverspensioen bij een uitvoerder naar keuze, naast de regeling van haar werkgever", "Een werknemer kan niet zelf een tweede werkgeverspensioen afsluiten."], ["Een verhoging van haar AOW door vrijwillig extra AOW-premie te betalen", "De AOW kan niet boven de volledige opbouw worden verhoogd door extra premie."]], "1g.10"],
["Jan (64) en Petra (63) scheiden na dertig jaar huwelijk. Jan werkte al die jaren fulltime, Petra zorgde grotendeels voor de kinderen en werkte weinig. Het ouderdomspensioen van Jan wordt volgens de Wvps verevend. Petra vraagt of zij daarnaast ook recht heeft op een deel van de AOW van Jan. Wat is juist?", [["Nee, de AOW valt niet onder de verevening; iedere partner bouwt een eigen AOW op", "De AOW is een volksverzekering waarvoor ieder een eigen recht opbouwt; de Wvps ziet alleen op aanvullend ouderdomspensioen."], ["Ja, zij heeft recht op de helft van de AOW die Jan tijdens het huwelijk heeft opgebouwd", "De AOW wordt niet verevend."], ["Ja, maar alleen als Petra zelf minder AOW heeft opgebouwd dan Jan", "Ook dan valt de AOW niet onder de verevening."], ["Alleen als zij de verdeling van de AOW in het echtscheidingsconvenant opnemen", "De AOW is een persoonlijk recht dat niet via een convenant kan worden verdeeld."]], "1h.18"],
["Geldt de Wet verevening pensioenrechten bij scheiding ook bij scheiding van tafel en bed?", [["Ja, ook bij scheiding van tafel en bed kan verevening plaatsvinden", "De Wvps noemt naast echtscheiding en beëindiging van een geregistreerd partnerschap ook scheiding van tafel en bed."], ["Nee, alleen bij een uitgesproken echtscheiding", "De wet beperkt verevening niet tot echtscheiding; ook scheiding van tafel en bed valt eronder."], ["Nee, omdat het huwelijk bij scheiding van tafel en bed blijft bestaan", "Hoewel het huwelijk formeel blijft bestaan, eindigt de gemeenschap en kan verevening gelden."], ["Alleen als de rechter dat afzonderlijk beveelt", "Verevening volgt uit de wet zelf; een afzonderlijk bevel van de rechter is niet nodig."]], "1h.18"],
["Erik (56) is dga van een bouwkundig adviesbureau. Hij heeft in zijn bv nog een pensioen in eigen beheer dat hij premievrij heeft laten staan. Erik en zijn vrouw Ingrid gaan na 22 jaar huwelijk scheiden. Erik meent dat zijn pensioen buiten de verdeling valt omdat het in zijn eigen bv zit. Geldt de Wvps voor dit pensioen?", [["Ja, de Wvps geldt ook voor pensioen in eigen beheer bij de bv", "De Wvps maakt geen onderscheid naar uitvoerder; ook pensioen in eigen beheer wordt verevend."], ["Nee, de Wvps geldt alleen voor pensioen bij een pensioenfonds", "De Wvps geldt voor pensioenaanspraken ongeacht of die bij een fonds, verzekeraar of eigen bv zijn ondergebracht."], ["Nee, want de Pensioenwet en dus ook de Wvps gelden niet voor een dga en zijn bv", "De Wvps is een aparte wet die ook voor pensioen in eigen beheer geldt."], ["Alleen als de bv in de jaren van het huwelijk winst heeft gemaakt", "De winst van de bv is niet bepalend voor de toepassing van de Wvps."]], "1j.16"],
["Wanneer kan conversie van pensioen bij scheiding plaatsvinden?", [["Als beide ex-partners dat overeenkomen en de pensioenuitvoerder meewerkt", "Conversie geeft de ex-partner een eigen recht; daarvoor zijn afspraken tussen partijen en instemming van de uitvoerder nodig."], ["Automatisch bij iedere scheiding, zonder dat de ex-partners iets hoeven af te spreken", "De standaard is verevening; conversie vraagt een uitdrukkelijke keuze van partijen."], ["Alleen als de deelnemer al met pensioen is", "Conversie kan juist vóór de pensioendatum worden overeengekomen."], ["Alleen op verzoek van de werkgever van de deelnemer", "De werkgever is geen partij bij de verdeling; het gaat om de ex-partners en de uitvoerder."]], "1h.18"],
["Willem (54) en Saar (52) zijn twee jaar geleden gescheiden. Zij hebben de scheiding op tijd bij het pensioenfonds van Willem gemeld, zodat Saar recht heeft op verevening. In de pensioenregeling van Willem is een partnerpensioen opgenomen. Willem overlijdt onverwacht, ruim voor zijn pensioendatum. Waarop heeft Saar dan in beginsel recht?", [["Op het bijzonder partnerpensioen, niet op een deel van Willems ouderdomspensioen", "Omdat Willem vóór zijn pensioendatum overlijdt, komt er geen ouderdomspensioen tot uitkering; Saar heeft wel recht op het bijzonder partnerpensioen."], ["Op de helft van Willems volledige ouderdomspensioen, uit te keren vanaf zijn pensioendatum", "Verevening volgt het ouderdomspensioen van Willem; bij zijn overlijden vóór de pensioendatum komt dat niet tot uitkering."], ["Op een Anw-uitkering als gescheiden partner van Willem", "Een gescheiden partner is geen nabestaande in de zin van de Anw."], ["Op uitbetaling van de afkoopwaarde van Willems opgebouwde pensioen", "Afkoop van het pensioen aan de ex-partner is niet het gevolg van overlijden."]], "1h.18"],
["Welke wet regelt in oktober 2026 de verdeling van pensioen bij scheiding?", [["De Wet verevening pensioenrechten bij scheiding (Wvps)", "De Wvps geldt sinds 1995; de beoogde opvolger met conversie als standaard is niet ingevoerd."], ["Een nieuwe wet met conversie als standaard, die de Wvps heeft vervangen", "Zo'n opvolger is wel voorgesteld, maar niet ingevoerd; de Wvps geldt nog."], ["De Wet toekomst pensioenen", "De Wtp hervormt het pensioenstelsel, maar regelt de verdeling bij scheiding niet zelfstandig."], ["Alleen het huwelijksvermogensrecht van het Burgerlijk Wetboek", "Voor pensioen geldt een aparte wet; het huwelijksvermogensrecht regelt andere vermogensbestanddelen."]], "1h.13"],
["Tom (40) en Mila (38) zijn tien jaar getrouwd geweest en gaan nu scheiden. Tom is fotograaf met een eigen onderneming en heeft tijdens het huwelijk een lijfrenteverzekering opgebouwd. Mila heeft in loondienst werkgeverspensioen opgebouwd. Zij vragen hoe de lijfrente van Tom wordt verdeeld. Wat is juist?", [["Via het huwelijksvermogensrecht, zoals verdeling of verrekening, en niet via de Wvps", "Een lijfrente is geen pensioen in de zin van de Wvps; de verdeling volgt uit het huwelijksvermogensrecht en hun afspraken."], ["Via standaardverevening van de Wvps, uitgevoerd door de verzekeraar", "De Wvps ziet op ouderdomspensioen uit werkgeverspensioen, niet op lijfrenten."], ["Niet, een lijfrente blijft altijd volledig van degene die de verzekering heeft gesloten", "Een lijfrente kan wel tot het te verdelen of te verrekenen vermogen behoren."], ["Door de lijfrente verplicht af te kopen en de netto opbrengst gelijk te verdelen", "Er is geen plicht tot afkoop; afkoop kan fiscaal juist ongunstig zijn."]], "1h.18"],
["Wat is een belangrijk risico van een pensioen of oudedagsverplichting die in de eigen bv van de dga is achtergebleven?", [["De uitkering hangt af van de financiële positie van de bv, bijvoorbeeld bij faillissement", "In eigen beheer is het vermogen niet afgescheiden; als de bv in problemen komt, kan de aanspraak waardeloos worden."], ["De aanspraak valt onder het prudentieel toezicht van DNB, net zoals dat bij een pensioenfonds het geval is", "Eigen beheer valt niet onder het prudentieel toezicht dat voor pensioenfondsen geldt."], ["De aanspraak wordt jaarlijks belast in box 3", "Een pensioen- of ODV-aanspraak valt onder de omkeerregel en niet in box 3."], ["De aanspraak vervalt automatisch bij de verkoop van de bv", "Bij verkoop moet de verplichting worden geregeld, maar zij vervalt niet vanzelf."]], "1j.19"],
["Een dga laat zijn bv premie betalen voor een externe pensioenregeling bij een verzekeraar. Hoe wordt die premie bij de bv fiscaal behandeld?", [["Als aftrekbare kosten binnen de fiscale grenzen van het Witteveenkader", "De premie is een beloningsbestanddeel voor de dga als werknemer; binnen de grenzen is zij aftrekbaar voor de vennootschapsbelasting."], ["Als winstuitkering aan de dga, die niet aftrekbaar is voor de bv", "Een zuivere pensioenpremie is een arbeidsbeloning, geen winstuitkering."], ["Als inkomen uit aanmerkelijk belang van de dga, belast in box 2 bij uitkering", "De premie wordt niet als dividend behandeld; zij valt onder de omkeerregel in de loonsfeer."], ["Als schenking aan de dga", "Er is geen sprake van een schenking; het gaat om een pensioentoezegging in het kader van de dienstbetrekking."]], "1j.20"],
["Marieke (60) is dga van een kledingwinkel en heeft haar pensioen in eigen beheer omgezet in een oudedagsverplichting. De winkel lijdt al jaren verlies en de bv heeft weinig vermogen over. Marieke rekent erop dat de ODV vanaf haar AOW-leeftijd een vast inkomen geeft. Zij vraagt haar adviseur of zij zich zorgen moet maken. Waarop moet de adviseur haar wijzen?", [["Dat de uitbetaling van de ODV onzeker is en zij haar oudedagsvoorziening breder moet bekijken", "Een ODV is een verplichting van de bv; als de bv onvoldoende middelen heeft, komt de uitkering in gevaar."], ["Dat de ODV door de Staat wordt gegarandeerd als de bv niet kan betalen", "Er is geen staatsgarantie voor een ODV."], ["Dat zij de ODV op elk moment zonder belasting of revisierente kan afkopen om het geld veilig te stellen", "Afkoop van een ODV buiten de regels is een onzuivere handeling met fiscale gevolgen."], ["Dat de ODV bij verliezen automatisch overgaat naar een pensioenfonds", "Een ODV gaat niet automatisch over naar een pensioenfonds."]], "1j.19"],
["Wat is een ondernemingspensioenfonds?", [["Een pensioenfonds voor één onderneming of een groep van verbonden ondernemingen", "Een OPF is opgericht voor één werkgever of concern; deelneming vloeit voort uit de arbeidsovereenkomst bij die werkgever."], ["Een fonds dat door de minister verplicht is gesteld voor alle werkgevers in een bedrijfstak", "Dat beschrijft een bedrijfstakpensioenfonds, niet een ondernemingspensioenfonds."], ["Een fonds waarin uitsluitend zelfstandigen deelnemen", "Zelfstandigen nemen niet deel aan een ondernemingspensioenfonds; dat is gekoppeld aan een werkgever."], ["Een verzekeraar die alleen premieregelingen uitvoert", "Een ondernemingspensioenfonds is een stichting, geen verzekeraar en ook niet beperkt tot premieregelingen."]], "1g.8"],
["Een werkgever sluit zich met zijn pensioenregeling aan bij een collectiviteitskring van een algemeen pensioenfonds (apf). Welk risico brengt dat met zich mee?", [["Bij een tekort in de kring kunnen de pensioenen in die kring worden gekort, los van de andere kringen", "Elke kring is financieel afgescheiden en heeft een eigen financiële positie; tegenvallers blijven binnen de kring."], ["Bij een tekort in een andere kring moet zijn kring altijd meebetalen", "Kringen zijn juist van elkaar afgescheiden."], ["De werkgever wordt mede-eigenaar van het apf en is aansprakelijk voor alle kringen", "Aansluiting maakt de werkgever niet aansprakelijk voor andere kringen."], ["De kring kan nooit meer worden verlaten, ook niet via collectieve waardeoverdracht", "Overstap naar een andere uitvoerder is mogelijk, bijvoorbeeld via collectieve waardeoverdracht."]], "1g.12"],
["Een deelnemer heeft een klacht over de uitvoering van zijn pensioen bij een pensioenfonds en is na de interne klachtenprocedure niet tevreden. Waar kan hij terecht?", [["Bij de Ombudsman Pensioenen", "De Ombudsman Pensioenen behandelt klachten over pensioenfondsen; klachten over verzekeraars en adviseurs gaan naar het Kifid."], ["Bij het Kifid, voor alle klachten over pensioenfondsen", "Het Kifid behandelt klachten over financiële dienstverleners zoals verzekeraars en adviseurs, niet over pensioenfondsen."], ["Bij de SVB, omdat die de pensioenen uitvoert", "De SVB voert de AOW en Anw uit en behandelt geen klachten over aanvullend pensioen."], ["Bij DNB, die individuele klachten beslecht", "DNB houdt prudentieel toezicht maar beslecht geen individuele geschillen."]], "1a.1"],
["Erwin is eigenaar van een schoonmaakbedrijf met 30 medewerkers. Al jaren heeft hij een goede eigen pensioenregeling bij een verzekeraar. Nu blijkt dat zijn bedrijf onder de verplichtstelling van het bedrijfstakpensioenfonds voor zijn sector valt. Hij wil zijn eigen regeling graag houden. Wat kan Erwin doen?", [["Onder voorwaarden vrijstelling van de verplichtstelling aanvragen bij het bedrijfstakpensioenfonds", "De regels voor vrijstelling maken het onder voorwaarden mogelijk om een eigen regeling te houden; de aanvraag gaat naar het fonds."], ["De verplichtstelling negeren, omdat hij al een eigen pensioenregeling heeft", "Een verplichtstelling geldt ook als er al een eigen regeling is; negeren kan leiden tot premieclaims."], ["De werknemers zelf laten kiezen bij welke uitvoerder zij willen gaan deelnemen", "De verplichtstelling laat geen individuele keuze voor werknemers toe."], ["Bij de AFM een ontheffing van de verplichtstelling aanvragen", "De AFM verleent geen vrijstelling van een verplichtstelling."]], "1g.8"],
["Een softwarebedrijf met 120 werknemers heeft al vijftien jaar een pensioenregeling bij een verzekeraar. Directeur Annelies (51) wil met ingang van volgend jaar overstappen naar een algemeen pensioenfonds. Zij wil dat de pensioenen die haar werknemers bij de verzekeraar hebben opgebouwd, ook naar het apf gaan. Zo hoeven de werknemers niet meerdere pensioenen bij te houden. Hoe heet deze overdracht?", [["Collectieve waardeoverdracht", "Bij een collectieve waardeoverdracht gaan de opgebouwde aanspraken van een groep deelnemers tegelijk over naar een andere uitvoerder."], ["Individuele waardeoverdracht per deelnemer", "Individuele waardeoverdracht hoort bij een baanwisseling van één werknemer."], ["Invaren", "Invaren is het omzetten van bestaande aanspraken naar een nieuwe premieregeling onder de Wtp."], ["Conversie", "Conversie is een term uit de verdeling van pensioen bij scheiding."]], "1g.4"],
["Wat houdt een garantiecontract bij een pensioenverzekeraar in?", [["De verzekeraar garandeert de uitkeringen en draagt het beleggings- en langlevenrisico", "Bij een garantiecontract staat de verzekeraar in voor de afgesproken uitkeringen, ongeacht het rendement."], ["De werkgever garandeert de werknemer een minimaal rendement op de ingelegde pensioenpremies", "Bij een garantiecontract is het juist de verzekeraar die garandeert, niet de werkgever."], ["De AFM garandeert het pensioen bij faillissement van de verzekeraar", "De AFM is een gedragstoezichthouder en geeft geen garanties op pensioenen."], ["De deelnemer krijgt gegarandeerd zijn ingelegde premie terug", "Restitutie van premie is een andere dekking; het garantiecontract ziet op de uitkeringen."]], "1g.11"],
["Peter (66) heeft een premieregeling bij een verzekeraar en gaat volgend jaar met pensioen. Hij wil zijn kapitaal omzetten in een vaste levenslange uitkering. De marktrente is het afgelopen jaar flink gedaald. De offerte die hij nu krijgt, valt daardoor lager uit dan een jaar geleden. Hoe komt dat?", [["Bij een lagere rente is meer kapitaal nodig voor dezelfde uitkering, dus koopt hij minder uitkering", "Een verzekeraar rekent met de rente; bij een lage rente is het kapitaal minder waard in levenslange uitkering."], ["De verzekeraar mag bij een dalende rente zijn kosten eenzijdig verdubbelen", "De lagere offerte komt door de rente, niet door een wettelijke kostenverhoging."], ["De lagere rente verlaagt zijn AOW, die met de uitkering wordt verrekend", "De AOW hangt niet af van de marktrente en wordt niet verrekend."], ["De rente heeft geen invloed; het verschil komt alleen door een hogere belasting", "De rente is juist een belangrijke factor bij de aankoop van een uitkering."]], "1h.15"],
["Een adviseur adviseert een klant over een lijfrenteverzekering. Hoe wordt hij voor dat advies beloond?", [["De klant betaalt hem rechtstreeks, omdat voor dit product een provisieverbod geldt", "Voor complexe financiële producten zoals levens- en lijfrenteverzekeringen mag de adviseur geen provisie van de aanbieder ontvangen."], ["De verzekeraar betaalt hem afsluitprovisie, verwerkt in de premie", "Provisie van de aanbieder is voor dit soort producten juist niet toegestaan."], ["De Belastingdienst vergoedt de advieskosten via de jaarruimte", "De Belastingdienst betaalt geen advieskosten; de klant betaalt de adviseur rechtstreeks."], ["De werkgever van de klant betaalt altijd de advieskosten", "Bij een individuele lijfrente is de werkgever geen partij; de klant betaalt zelf."]], "4a.4"],
["Een klant is ontevreden over het pensioenadvies van zijn financieel adviseur en komt er met het kantoor niet uit. Waar kan hij met zijn klacht terecht?", [["Bij het Klachteninstituut Financiële Dienstverlening (Kifid)", "Financiële dienstverleners moeten zijn aangesloten bij het Kifid, dat klachten van consumenten over advies behandelt."], ["Bij de Ombudsman Pensioenen, die alle pensioenklachten behandelt", "De Ombudsman Pensioenen behandelt klachten over pensioenfondsen, niet over financieel adviseurs."], ["Bij de SVB", "De SVB voert volksverzekeringen uit en behandelt geen klachten over adviseurs."], ["Bij de Autoriteit Persoonsgegevens", "De AP ziet op privacy; zij behandelt geen inhoudelijke klachten over financieel advies."]], "1a.1"],
["Karin (48) is na vijftien jaar overgestapt van een zorginstelling naar een gemeente. Haar oude pensioen staat premievrij bij het pensioenfonds van de zorg, haar nieuwe pensioen bouwt zij op bij het fonds van de nieuwe werkgever. Zij heeft een brief ontvangen over de mogelijkheid van waardeoverdracht. Karin vraagt haar adviseur of ze het oude pensioen moet laten overdragen. Wat hoort in elk geval bij een zorgvuldig advies?", [["De regelingen vergelijken op onder meer financiële positie, indexatie, nabestaandendekking en kosten", "Waardeoverdracht kan voor- of nadelig uitpakken; dat blijkt pas na vergelijking van de belangrijkste kenmerken van beide regelingen."], ["Altijd adviseren om over te dragen, omdat één pensioen bij één uitvoerder voor haar overzichtelijker is", "Overzichtelijkheid is geen goede reden als de oude regeling betere voorwaarden heeft."], ["Adviseren de waarde af te kopen en in een lijfrente te storten", "Afkoop van een pensioen is in beginsel niet toegestaan en overdracht naar een lijfrente kan niet."], ["Alleen kijken naar de hoogte van de overdrachtswaarde die het oude fonds noemt", "De hoogte van de waarde zegt weinig zonder vergelijking van wat zij er in de nieuwe regeling voor terugkrijgt."]], "1h.4"],
["Hoe moeten pensioenuitvoerders hun informatie aan deelnemers in beginsel verstrekken?", [["Elektronisch, tenzij de deelnemer kiest voor informatie op papier", "De Wet pensioencommunicatie maakt digitale informatie de standaard, met een recht op papier voor wie dat wil."], ["Uitsluitend per post, om bereikbaarheid te garanderen", "Digitaal is juist het uitgangspunt geworden; papier blijft mogelijk op verzoek."], ["Uitsluitend via de werkgever, op het intranet van het bedrijf", "De uitvoerder is zelf verantwoordelijk voor de informatie en mag niet volstaan met intranet van de werkgever."], ["Alleen mondeling tijdens een persoonlijk gesprek", "Mondelinge informatie volstaat niet; de wet vraagt informatie die vastligt en toegankelijk is."]], "1g.13"],
["Een installatiebedrijf heeft een premieregeling waarin de premie een vast percentage van de pensioengrondslag is. De directie verwacht de komende jaren te groeien van 50 naar 70 werknemers met vergelijkbare salarissen. Wat betekent dat voor de pensioenlasten?", [["De pensioenlasten stijgen ongeveer evenredig met de som van de pensioengrondslagen", "Bij een vast premiepercentage groeien de lasten mee met het aantal deelnemers en hun pensioengrondslag."], ["De pensioenlasten blijven gelijk, omdat het premiepercentage niet verandert", "Een gelijk percentage over meer grondslagen geeft hogere totale lasten."], ["De pensioenlasten dalen door schaalvoordeel tot onder het huidige niveau", "Schaalvoordeel kan de kosten iets drukken, maar het totaal stijgt met de groei."], ["De lasten zijn niet in te schatten, omdat zij afhangen van de dekkingsgraad van de verzekeraar", "Bij een premieregeling volgen de lasten uit de afgesproken premie."]], "1h.20"],
["Paul (61) werkt als projectleider bij een ingenieursbureau. Hij is gezond, maar wil graag op zijn 63e stoppen met werken om meer tijd met zijn kleinkinderen door te brengen. Zijn vrouw werkt nog parttime en heeft een eigen klein pensioen. Paul vraagt zijn adviseur of hij het zich kan veroorloven om op 63 jaar met pensioen te gaan. Wat moet de adviseur in elk geval in beeld brengen?", [["Het inkomen vóór en na de AOW-leeftijd, het effect van vervroegen en de netto koopkracht", "Bij vervroegen ontstaat een periode zonder AOW en wordt het pensioen lager; het netto besteedbaar inkomen is bepalend."], ["Alleen de bruto pensioenuitkering op 63 jaar zoals die op zijn Uniform Pensioenoverzicht staat vermeld", "Het bruto pensioen zegt weinig zonder de AOW-periode, belasting en het effect op het hele huishouden."], ["Alleen de hoogte van zijn AOW, omdat die bepalend is voor zijn inkomen", "De AOW is maar één bron en gaat bovendien pas later in."], ["De mogelijkheid om zijn AOW al vanaf 63 jaar te laten ingaan", "De AOW kan niet worden vervroegd."]], "1h.14"],
["Een klant zegt dat hij de pensioenbrieven van zijn fonds nooit leest omdat hij het te ingewikkeld vindt. Welke aanpak past het best bij de zorgplicht van een adviseur?", [["De kern samen doornemen in begrijpelijke taal en de keuzes en risico's voor hem toelichten", "Een goede adviseur sluit aan bij het kennisniveau van de klant en maakt de kern van de pensioeninformatie begrijpelijk."], ["Hem adviseren de brieven te negeren, omdat zijn pensioen via de werkgever toch wel goed geregeld is", "Zo blijft de klant onwetend over keuzes en risico's; dat past niet bij zorgvuldige dienstverlening."], ["Hem doorverwijzen naar de AFM voor uitleg over zijn regeling", "De AFM geeft geen individuele uitleg over pensioenregelingen."], ["De brieven namens hem beantwoorden zonder overleg", "Zonder overleg handelen past niet bij een adviesrelatie; de klant moet zelf weloverwogen kunnen kiezen."]], "2j.4"],
["Henk overlijdt op 68-jarige leeftijd. Hij was hertrouwd met Ans, die nu partnerpensioen ontvangt van het pensioenfonds van Henk. Henk heeft twee kinderen uit zijn eerste huwelijk. Zij vinden dat het partnerpensioen tot de erfenis behoort en willen hun deel. Wat is juist?", [["Het partnerpensioen is een eigen recht van Ans en valt niet in de nalatenschap", "Partnerpensioen is een rechtstreeks recht van de nabestaande partner tegenover de uitvoerder en hoort niet bij de erfenis."], ["Het partnerpensioen valt in de nalatenschap en wordt volgens het testament verdeeld", "Het partnerpensioen behoort niet tot de nalatenschap."], ["De kinderen kunnen hun legitieme portie berekenen over de contante waarde van het partnerpensioen", "Omdat het partnerpensioen geen deel van de nalatenschap is, telt het niet mee voor de legitieme portie."], ["Het pensioenfonds verdeelt het partnerpensioen gelijk over Ans en alle kinderen", "Het partnerpensioen is voor de partner; kinderen kunnen hooguit een eigen wezenpensioen hebben."]], "1h.16"],
["Lars (57) is na 28 jaar ontslagen bij een reorganisatie en heeft nog geen nieuwe baan. Hij ontvangt een WW-uitkering. Lars wil voorkomen dat zijn pensioenopbouw stilvalt, omdat hij al op leeftijd is. Hij vraagt of hij de opbouw bij zijn oude pensioenfonds kan voortzetten. Wat is in het algemeen mogelijk?", [["Vrijwillige voortzetting voor een beperkte periode, als het reglement dat toestaat en hij zelf de premie betaalt", "Veel regelingen staan vrijwillige voortzetting toe na ontslag; de deelnemer betaalt dan zelf en de duur is fiscaal begrensd."], ["Onbeperkte voortzetting tot zijn AOW-leeftijd, waarbij de oude werkgever gewoon de volledige premie blijft betalen", "Er is geen onbeperkte voortzetting en de oude werkgever betaalt na het einde van het dienstverband niet meer."], ["Voortzetting via de WW, waarbij het UWV automatisch de volledige pensioenpremie overneemt", "Het UWV neemt de pensioenpremie niet automatisch over tijdens de WW."], ["Geen enkele mogelijkheid, omdat zijn aanspraken bij ontslag direct worden afgekocht", "Opgebouwde aanspraken blijven premievrij bestaan en worden niet zomaar afgekocht."]], "1h.16"],
["Wat is een pensioenreglement?", [["Het document van de uitvoerder waarin de rechten en plichten van deelnemers onder de regeling zijn vastgelegd", "Het reglement werkt de pensioenovereenkomst uit en bepaalt onder meer wie partner is, welke keuzes er zijn en hoe het pensioen wordt berekend."], ["De wettelijke regeling waarin de overheid de hoogte van alle aanvullende pensioenen bepaalt", "De overheid bepaalt de hoogte van aanvullend pensioen niet; die volgt uit de afspraken van werkgever en werknemers."], ["Het jaarlijkse overzicht met opgebouwde aanspraken dat iedere deelnemer van de uitvoerder ontvangt", "Dat is het Uniform Pensioenoverzicht; het reglement bevat de regels van de pensioenregeling zelf."], ["De overeenkomst tussen werkgever en uitvoerder over premiebetaling en de te leveren diensten", "Dat is de uitvoeringsovereenkomst; het reglement regelt de verhouding tussen uitvoerder en deelnemer."]], "1i.1"]
];
